/* ---------- build food table ---------- */
const FOODS = RAW.map(r=>({id:r[0],name:r[1],emoji:r[2],cat:r[3],serving:r[4],carbs:r[5],fiber:r[6],protein:r[7],fat:r[8],gi:r[9],src:r[10],alts:r[11]}));
const F = Object.fromEntries(FOODS.map(f=>[f.id,f]));
for(const [id,name,emoji,parts] of MEALS){
  let c=0,gc=0,fib=0,p=0,fat=0; const ok=parts.filter(([pid])=>F[pid]);
  for(const [pid,q] of ok){ const f=F[pid]; c+=f.carbs*q; gc+=f.gi*f.carbs*q; fib+=f.fiber*q; p+=f.protein*q; fat+=f.fat*q; }
  const m={id,name,emoji,cat:'meals',serving:'1 meal',carbs:c,fiber:fib,protein:p,fat:fat,gi:c?gc/c:0,src:'C',alts:[],parts:ok};
  FOODS.push(m); F[id]=m;
}
for(const [nd,name,grp,serving,c,fib,p,fat,gi] of USDA){ const f={id:'usda_'+nd,name,emoji:USDA_GROUPS[grp][1],cat:'usda',grp,serving,carbs:c,fiber:fib,protein:p,fat,gi,src:'U',alts:[]}; FOODS.push(f); F[f.id]=f; }
CATS.push(['usda','USDA database']);
const SIDES = new Set(['kimchi','miso_soup','guacamole','hummus','baba_ganoush','olives','cheese','maple_syrup','sambar','rasam','coco_chutney','tomato_chutney','veg_kurma','veg_stew','kadala_curry','avial','papad','pickle','jam','sugar','honey','jaggery','salad','raita','curd','hung_curd']);
const ADDONS = ['salad','raita','curd','eggs','paneer_tikka','grilled_chicken','sprouts','almonds','toor_dal','hung_curd'];
const SRC = {T:'GI from international tables', I:'GI from Indian studies', E:'GI estimated', C:'GI computed from its parts', U:'Nutrients from USDA, GI estimated by food group'};
const CATNAME = Object.fromEntries(CATS);

/* ---------- model ---------- */
const PROF = { none:{base:90,k:2.0,R:95,a:2.8,lag:0,lim:[130,150]}, pre:{base:104,k:3.0,R:140,a:2.0,lag:8,lim:[140,180]}, t2:{base:135,k:4.6,R:230,a:1.6,lag:15,lim:[180,220]} };
function expand(plate){ const out=new Map(); for(const [id,q] of plate){ const f=F[id]; if(!f) continue; if(f.parts){ for(const [pid,pq] of f.parts) out.set(pid,(out.get(pid)||0)+pq*q); } else out.set(id,(out.get(id)||0)+q); } return out; }
function nutr(plate){
  let c=0,gc=0,fib=0,p=0,fat=0;
  for(const [id,q] of plate){ const f=F[id]; if(!f) continue; c+=f.carbs*q; gc+=f.gi*f.carbs*q; fib+=f.fiber*q; p+=f.protein*q; fat+=f.fat*q; }
  const gi=c>0?gc/c:0; return {carbs:c,gi,gl:gi*c/100,fiber:fib,protein:p,fat};
}
function predict(plate, pk, h){
  const P=PROF[pk], n=nutr(plate);
  const slowing = 1 + 0.006*n.protein + 0.005*n.fat + 0.02*n.fiber;
  const hab = (h.order?0.75:1)*(h.walk?0.8:1);
  const raw = n.gl*P.k/slowing*hab;
  const rise = P.R*(1-Math.exp(-raw/P.R));
  const tp = 24 + (1-Math.min(n.gi,100)/100)*30 + Math.min(25, n.fat*0.6+n.protein*0.25) + P.lag + (h.order?8:0);
  return {n, rise, peak:P.base+rise, tp, base:P.base, a:P.a};
}
function curveAt(pr,t){ if(t<=0) return pr.base; const x=t/pr.tp; return pr.base + pr.rise*Math.pow(x,pr.a)*Math.exp(pr.a*(1-x)); }
function scoreOf(plate,h){ const pr=predict(plate,'none',h); return Math.max(1,Math.min(10,Math.round(10 - Math.max(0,pr.rise-10)/8))); }
const NOH={order:false,walk:false};
FOODS.forEach(f=>{ const p=new Map([[f.id,1]]); f._score=scoreOf(p,NOH); f._peak=Math.round(predict(p,'none',NOH).peak); });
const cls = s => s>=7?'g':s>=4?'a':'r';
function colFor(peak,pk){ const l=PROF[pk].lim; return peak>=l[1]?'var(--red)':peak>=l[0]?'var(--amber)':'var(--green)'; }
function zoneText(pk,peak){
  if(pk==='none') return peak<130?'Steady. Stays well under 140.':peak<150?'Moderate spike, around the 140 limit.':'High spike for someone without diabetes.';
  if(pk==='pre') return peak<140?'Steady for prediabetes.':peak<180?'Moderate spike. Worth softening.':'High spike. See how to steady it below.';
  return peak<180?'Within the usual 180 after-meal target.':peak<220?'Above the 180 target.':'Well above target.';
}
function swapsFor(id){
  const f=F[id]; if(!f || f.cat==='meals') return [];
  const out=[...f.alts.filter(a=>F[a])];
  if(out.length<3){ FOODS.filter(g=>g.cat===f.cat && (f.cat!=='usda'||(g.grp===f.grp && g.name.split(',')[0]===f.name.split(',')[0] && !/raw|dry mix|powder|unprepared/i.test(g.name))) && g.id!==id && !out.includes(g.id) && !SIDES.has(g.id) && !SIDES.has(id) && g._peak < f._peak-3 && g.carbs>=f.carbs*0.4).sort((a,b)=>a._peak-b._peak).slice(0,3-out.length).forEach(g=>out.push(g.id)); }
  return out;
}
function whySwap(a,b){
  if(b.carbs<2) return 'It has almost no carbohydrate, so it barely moves glucose.';
  const parts=[];
  if(b.gi<=a.gi-8) parts.push(`a lower GI (${b.gi} vs ${a.gi})`);
  if(b.carbs<=a.carbs-5) parts.push(`${Math.round(a.carbs-b.carbs)} g fewer carbs`);
  if(b.protein>=a.protein+4) parts.push('more protein');
  if(b.fiber>=a.fiber+2) parts.push('more fibre');
  return parts.length ? 'It has '+parts.join(', ').replace(/, ([^,]*)$/,' and $1')+'.' : 'It releases glucose more slowly.';
}
function whyAdd(f){ return f.fiber>=2&&f.protein<5 ? 'Fibre slows digestion. Eat it first for the biggest effect.' : `It adds ${Math.round(f.protein)} g of protein, which slows how fast carbs reach your blood.`; }
const fmtQ = q => (Number.isInteger(q)?q:q.toFixed(1))+'×';
const settleText = pr => { for(let t=Math.ceil(pr.tp);t<=180;t++){ if(curveAt(pr,t)<pr.base+10){ return t>=60?`${Math.floor(t/60)} h${t%60?' '+Math.round(t%60/5)*5+' min':''}`:`${t} min`; } } return null; };

/* ---------- chart ---------- */
function pathFor(pr,X,Y){ let d=''; for(let t=0;t<=180;t+=3){ d+=(t?'L':'M')+X(t).toFixed(1)+','+Y(curveAt(pr,t)).toFixed(1); } return d; }
function drawChart(svg, pr, ghost, pk, gid, ghostLabel){
  const W=600,H=250,L=44,R=10,T=22,B=30;
  const lo=Math.floor((pr.base-20)/10)*10;
  const top=Math.max(pk==='none'?190:240, Math.ceil(((ghost?Math.max(ghost.peak,pr.peak):pr.peak)+20)/20)*20);
  const X=t=>L+(W-L-R)*t/180, Y=v=>T+(H-T-B)*(1-(v-lo)/(top-lo));
  const col=colFor(pr.peak,pk);
  let s=`<defs><linearGradient id="${gid}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${col}" stop-opacity=".25"/><stop offset="1" stop-color="${col}" stop-opacity="0"/></linearGradient></defs>`;
  for(const v of [140,180]){ if(v<top&&v>lo){ s+=`<line x1="${L}" x2="${W-R}" y1="${Y(v)}" y2="${Y(v)}" stroke="var(--line-2)" stroke-dasharray="3 5"/><text x="${W-R}" y="${Y(v)-6}" text-anchor="end">${v===140?'140 healthy limit':'180 diabetes target'}</text>`; } }
  for(const t of [0,60,120,180]) s+=`<text x="${X(t)}" y="${H-6}" text-anchor="${t===0?'start':t===180?'end':'middle'}">${t===0?'Eat':t/60+' h'}</text>`;
  s+=`<text x="${L-8}" y="${Y(pr.base)+4}" text-anchor="end">${pr.base}</text><line x1="${L}" x2="${W-R}" y1="${Y(pr.base)}" y2="${Y(pr.base)}" stroke="var(--line)"/>`;
  if(ghost) s+=`<path d="${pathFor(ghost,X,Y)}" fill="none" stroke="var(--txt-faint)" stroke-width="2" stroke-dasharray="5 5" opacity=".75"/><text x="${L+4}" y="${T+2}" style="fill:var(--txt-faint)">- - ${ghostLabel||'without habits'}</text>`;
  const d=pathFor(pr,X,Y);
  s+=`<path d="${d}L${X(180)},${Y(lo)}L${X(0)},${Y(lo)}Z" fill="url(#${gid})"/><path class="curve" d="${d}" fill="none" stroke="${col}" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"/>`;
  if(pr.rise>1){ const px=X(pr.tp),py=Y(pr.peak); s+=`<circle cx="${px}" cy="${py}" r="5.5" fill="${col}" stroke="var(--card)" stroke-width="2"/><text x="${px}" y="${py-13}" text-anchor="middle" style="fill:var(--txt);font-weight:700">${Math.round(pr.peak)}</text>`; }
  svg.innerHTML=s;
}

/* ---------- state ---------- */
let plate=new Map(), prof='none', cat='all', query='';
try{ const s=JSON.parse(localStorage.getItem('mytr-spike-lab')||'null'); if(s){ plate=new Map((s.plate||[]).filter(([id])=>F[id])); prof=PROF[s.prof]?s.prof:'none'; $('order').checked=!!s.order; $('walk').checked=!!s.walk; } }catch(e){}
function save(){ try{ localStorage.setItem('mytr-spike-lab', JSON.stringify({plate:[...plate],prof,order:$('order').checked,walk:$('walk').checked})); }catch(e){} }
const habits=()=>({order:$('order').checked, walk:$('walk').checked});
const link = id => '#food/'+id;

/* ---------- marquee & stats ---------- */
const chip=f=>`<a class="mchip" href="${link(f.id)}"><span class="e">${f.emoji}</span>${escapeHTML(f.name)}<span class="s score ${cls(f._score)}">${f._score}</span></a>`;
const pick1=['idli_coffee','masala_dosa_coffee','chicken_biryani','poha','chapati','white_rice','rajma_chawal','samosa_chai','filter_coffee','pesarattu','curd','gulab_jamun','banana','paneer_tikka','upma','south_meals'];
const pick2=['vada_pav','salad','pav_bhaji','foxtail','mango','jalebi','chole_bhature','eggs','sabudana','dal_chawal','naan','guava','cola','moong_chilla','pongal_vada_coffee','sprouts'];
/* hero marquee and stats replaced by the live curve */

/* ---------- food grid ---------- */
function card(f){
  const q=plate.get(f.id)||0;
  return `<article class="food${q?' on':''}">
    <a class="cover" href="${link(f.id)}" aria-label="${escapeHTML(f.name)}: details and how to steady it"></a>
    <span class="added">${q?fmtQ(q):''}</span>
    <span class="e" aria-hidden="true">${f.emoji}</span>
    ${f.parts?'<span class="tag-meal">Meal</span>':''}
    <span class="n">${escapeHTML(f.name)}</span><span class="sv">${f.parts?f.parts.length+' parts':escapeHTML(f.serving)}</span>
    <span class="meta"><span>${Math.round(f.carbs)} g carbs</span><span class="score ${cls(f._score)}">${f._score}/10</span></span>
    <button class="plus" type="button" data-add="${f.id}" aria-label="Add ${escapeHTML(f.name)} to plate">+</button>
  </article>`;
}
$('cats').innerHTML=CATS.map(([k,l])=>`<button class="cat" type="button" data-cat="${k}" aria-pressed="${k===cat}">${l}</button>`).join('');
$('cats').addEventListener('click',e=>{ const b=e.target.closest('[data-cat]'); if(!b) return; cat=b.dataset.cat; $('cats').querySelectorAll('.cat').forEach(x=>x.setAttribute('aria-pressed',x===b)); renderFoods(); $('scroller').scrollTop=0; });
$('q').addEventListener('input',e=>{ query=e.target.value.trim().toLowerCase(); if(query){ cat='all'; $('cats').querySelectorAll('.cat').forEach(x=>x.setAttribute('aria-pressed',x.dataset.cat==='all')); } renderFoods(); });
let shownList=[], shownN=0, subgrp='all';
const PAGE=120;
function matches(f,toks){ if(!toks.length) return true; const n=(f._lc||(f._lc=f.name.toLowerCase()+(f.parts?' '+f.parts.map(([p])=>F[p].name.toLowerCase()).join(' '):''))); return toks.every(t=>n.includes(t)); }
function renderSub(){
  const el=$('subcats');
  if(cat!=='usda'){ el.hidden=true; return; }
  el.hidden=false;
  el.innerHTML=`<button class="cat sub" type="button" data-sub="all" aria-pressed="${subgrp==='all'}">All groups</button>`+Object.entries(USDA_GROUPS).map(([k,[n,e]])=>`<button class="cat sub" type="button" data-sub="${k}" aria-pressed="${subgrp===k}">${e} ${n}</button>`).join('');
}
function renderFoods(){
  const toks=query.split(/\s+/).filter(Boolean);
  const list=FOODS.filter(f=>(cat==='all'||f.cat===cat) && (cat!=='usda'||subgrp==='all'||f.grp===subgrp) && matches(f,toks));
  shownList = (cat==='all') ? [...list.filter(f=>f.parts), ...list.filter(f=>!f.parts&&f.src!=='U'), ...list.filter(f=>f.src==='U')] : list;
  const nf=new Intl.NumberFormat('en-IN');
  $('count').textContent = `${nf.format(shownList.length)} ${shownList.length===1?'item':'items'}${cat!=='all'?' in '+(cat==='usda'&&subgrp!=='all'?USDA_GROUPS[subgrp][0]:CATNAME[cat]).toLowerCase():''}${query?' matching "'+query+'"':''}`;
  shownN=Math.min(PAGE,shownList.length);
  $('foods').innerHTML = shownList.length ? shownList.slice(0,shownN).map(card).join('') : `<div class="nores">No match for "${escapeHTML(query)}". Try fewer words, like "rice", "dosa" or "coffee".</div>`;
  renderSub();
}
function moreFoods(){ if(shownN>=shownList.length) return; const next=shownList.slice(shownN,shownN+PAGE); shownN+=next.length; $('foods').insertAdjacentHTML('beforeend',next.map(card).join('')); }
new IntersectionObserver(es=>{ if(es[0].isIntersecting) moreFoods(); },{root:$('scroller'),rootMargin:'0px 0px 600px 0px'}).observe($('sentinel'));
$('subcats').addEventListener('click',e=>{ const b=e.target.closest('[data-sub]'); if(!b) return; subgrp=b.dataset.sub; renderFoods(); $('scroller').scrollTop=0; });
document.addEventListener('click',e=>{ const a=e.target.closest('[data-add]'); if(!a) return; e.preventDefault(); add(a.dataset.add,1); toast(`${F[a.dataset.add].name} added to plate`); });
function add(id,d){ if(d>0 && plate.size===0 && !slStartAttempt()) return; const q=Math.max(0,(plate.get(id)||0)+d); if(q<=0) plate.delete(id); else plate.set(id,Math.round(q*2)/2); update(); }

/* ---------- profiles ---------- */
function setProf(p){ prof=p; document.querySelectorAll('[data-p]').forEach(x=>x.setAttribute('aria-pressed',x.dataset.p===prof)); update(); if(typeof renderHero==='function'&&$('hChips').children.length) renderHero(); if(currentDetail) renderDetail(currentDetail,true); }
document.querySelectorAll('[data-p]').forEach(b=>b.addEventListener('click',()=>setProf(b.dataset.p)));
document.querySelectorAll('[data-p]').forEach(x=>x.setAttribute('aria-pressed',x.dataset.p===prof));
['order','walk'].forEach(id=>$(id).addEventListener('change',update));
$('clear').addEventListener('click',()=>{ plate.clear(); update(); });

/* ---------- plate ---------- */
function renderPlate(pr){
  const ul=$('items');
  if(!plate.size){ ul.innerHTML=`<li style="border:0;display:block"><div class="empty"><span class="e">🍽</span>Your plate is empty. Tap + on any food, or try <button class="linkbtn" type="button" id="demo">idli with filter coffee</button>.</div></li>`;
    $('demo').addEventListener('click',()=>{ if(!slStartAttempt()) return; plate=new Map([['idli_coffee',1]]); update(); });
  } else ul.innerHTML=[...plate].map(([id,q])=>{ const f=F[id]; return `<li><span class="e" aria-hidden="true">${f.emoji}</span><span class="n"><a href="${link(id)}">${escapeHTML(f.name)}</a><small>${escapeHTML(f.serving)} · ${Math.round(f.carbs*q)} g carbs</small></span>
    <span class="step"><button type="button" data-step="${id}" data-d="-0.5" aria-label="Less ${escapeHTML(f.name)}">−</button><span>${fmtQ(q)}</span><button type="button" data-step="${id}" data-d="0.5" aria-label="More ${escapeHTML(f.name)}">+</button></span></li>`; }).join('');
  const n=pr.n;
  $('totals').innerHTML=[['Carbs',Math.round(n.carbs)+' g'],['Fibre',Math.round(n.fiber)+' g'],['Protein',Math.round(n.protein)+' g'],['Fat',Math.round(n.fat)+' g'],['GL',Math.round(n.gl)]].map(([k,v])=>`<div><b>${v}</b><span>${k}</span></div>`).join('');
}
$('items').addEventListener('click',e=>{ const b=e.target.closest('[data-step]'); if(b) add(b.dataset.step,+b.dataset.d); });

/* ---------- plate suggestions ---------- */
function plateWith(base,fn){ const p=new Map(base); fn(p); return p; }
function suggestions(cur){
  const h=habits(), out=[];
  for(const [id,q] of plate){ for(const alt of swapsFor(id)){ if(plate.has(alt)) continue; const p=plateWith(plate,m=>{m.delete(id);m.set(alt,q);}); const dlt=cur.peak-predict(p,prof,h).peak; if(dlt>=4) out.push({type:'Swap',from:id,to:alt,delta:dlt,act:()=>{plate.delete(id);plate.set(alt,q);},why:whySwap(F[id],F[alt])}); } }
  const big=[...plate].filter(([id])=>!F[id].parts).map(([id,q])=>({id,q,c:F[id].carbs*q})).sort((a,b)=>b.c-a.c)[0];
  if(big&&big.c>=25){ const nq=Math.max(0.5,big.q/2); if(nq<big.q){ const dlt=cur.peak-predict(plateWith(plate,m=>m.set(big.id,nq)),prof,h).peak; if(dlt>=4) out.push({type:'Portion',from:big.id,delta:dlt,act:()=>plate.set(big.id,nq),why:`Half the ${F[big.id].name.toLowerCase()} removes about ${Math.round(big.c-F[big.id].carbs*nq)} g of carbs. Fill the space with vegetables.`}); } }
  const hasCarb=cur.n.carbs>=15;
  if(hasCarb) for(const id of ADDONS){ if(plate.has(id)) continue; const dlt=cur.peak-predict(plateWith(plate,m=>m.set(id,1)),prof,h).peak; if(dlt>=3) out.push({type:'Add',to:id,delta:dlt,act:()=>plate.set(id,1),why:whyAdd(F[id])}); }
  if(hasCarb&&!h.order){ const dlt=cur.peak-predict(plate,prof,{...h,order:true}).peak; if(dlt>=3) out.push({type:'Habit',icon:'🔁',label:'Eat vegetables and protein first',delta:dlt,act:()=>{$('order').checked=true;},why:'Same food, different order. Start with salad, dal, or curd and finish with rice or roti.'}); }
  if(hasCarb&&!h.walk){ const dlt=cur.peak-predict(plate,prof,{...h,walk:true}).peak; if(dlt>=3) out.push({type:'Habit',icon:'🚶',label:'Walk 10 to 15 minutes after',delta:dlt,act:()=>{$('walk').checked=true;},why:'A gentle walk soon after eating lets your muscles use glucose as it arrives.'}); }
  const seen=new Set(),res=[]; out.sort((a,b)=>b.delta-a.delta).forEach(s=>{ const k=s.type+(s.from||'')+(s.to||s.label||''); if(!seen.has(k)){ seen.add(k); res.push(s); } });
  const sw=res.filter(s=>s.type==='Swap'||s.type==='Portion').slice(0,4), ad=res.filter(s=>s.type==='Add').slice(0,2), hb=res.filter(s=>s.type==='Habit');
  return [...sw,...hb,...ad].sort((a,b)=>b.delta-a.delta).slice(0,8);
}
function renderSugg(cur){
  const g=$('sugg');
  if(!plate.size){ g.innerHTML=''; $('suggSub').textContent='Add a meal above and we\'ll suggest swaps, add-ons, and habits that lower its spike.'; return; }
  const list=suggestions(cur);
  if(!list.length){ $('suggSub').textContent='This plate is already steady. Nice work.'; g.innerHTML='<div class="sug-empty">Nothing here moves the peak by more than a few mg/dL. Keep portions as they are, and enjoy it.</div>'; return; }
  $('suggSub').textContent=`Ranked by how much each change lowers the predicted peak for the ${prof==='none'?'no diabetes':prof==='pre'?'prediabetes':'type 2'} profile. Tap Apply to try it.`;
  g.innerHTML=list.map((s,i)=>{
    let head;
    if(s.type==='Swap'){ const a=F[s.from],b=F[s.to]; head=`<div class="swap"><span class="e from" aria-hidden="true">${a.emoji}</span><span class="arr">→</span><span class="e" aria-hidden="true">${b.emoji}</span><span class="names"><span class="from">${escapeHTML(a.name)}</span><br>${escapeHTML(b.name)}</span></div>`; }
    else if(s.type==='Portion'){ const a=F[s.from]; head=`<div class="swap"><span class="e" aria-hidden="true">${a.emoji}</span><span class="names">Half portion of ${escapeHTML(a.name.toLowerCase())}</span></div>`; }
    else if(s.type==='Add'){ const b=F[s.to]; head=`<div class="swap"><span class="e" aria-hidden="true">${b.emoji}</span><span class="names">Add ${escapeHTML(b.name.toLowerCase())}<br><small style="color:var(--txt-faint);font-weight:500">${escapeHTML(b.serving)}</small></span></div>`; }
    else head=`<div class="swap"><span class="e" aria-hidden="true">${s.icon}</span><span class="names">${s.label}</span></div>`;
    return `<div class="sug"><span class="type">${s.type}</span>${head}<p class="why">${s.why}</p><div class="foot"><span class="delta">−${Math.round(s.delta)}<small>mg/dL peak</small></span><button class="btn-sm" type="button" data-sug="${i}">Apply</button></div></div>`;
  }).join('');
  g.querySelectorAll('[data-sug]').forEach(b=>b.addEventListener('click',()=>{ list[+b.dataset.sug].act(); update(); toast('Applied. Curve updated.'); }));
}

/* ---------- zones ---------- */
function renderZones(){
  const sorted=FOODS.filter(f=>f.carbs>=10&&f.src!=='U').sort((a,b)=>a._peak-b._peak);
  const row=f=>`<a class="zrow" href="${link(f.id)}"><span class="e" aria-hidden="true">${f.emoji}</span><span class="n">${escapeHTML(f.name)}<small>${escapeHTML(f.serving)} · GI ${Math.round(f.gi)}${f.src==='E'?' (estimated)':''}</small></span><span class="pk">${f._peak}<small>mg/dL peak</small></span><span class="score ${cls(f._score)}">${f._score}</span></a>`;
  $('ztop').innerHTML=sorted.slice(0,12).map(row).join('');
  $('zbot').innerHTML=sorted.slice(-12).reverse().map(row).join('');
}


/* ---------- plate visual ---------- */
const DRINK=id=>F[id]&&(F[id].cat==='drinks'||/coffee|chai|tea|lassi|juice|milk|cola|soda|buttermilk|shake/.test(id));
const SMALLSIDE=new Set(['pickle','papad','podi','coco_chutney','tomato_chutney','jam','sugar','honey','jaggery','kimchi','olives','guacamole','hummus','baba_ganoush']);
function moundColor(f){
  const id=f.id, n=f.name.toLowerCase();
  const rules=[[/biryani|jollof|tomato_rice|nasi|fried_rice|paella|pulao/,'#E3A64B'],[/lemon_rice|khichdi|pongal|upma|poha|sabudana|bisibele/,'#EBCB6B'],[/curd_rice|white_rice|basmati|jasmine|sticky|ghee_rice|idli|cauli_rice|congee|rice_noodles|onigiri|appam/,'#F4F1EA'],
    [/brown_rice|red_rice|foxtail|millet|kodo|quinoa|barley|bulgur|couscous|ragi|puttu/,'#C9A27A'],[/rajma|chole|kadala|black_beans|refried|mutton|butter_chicken|bolognese|egusi|doro/,'#8E3B24'],
    [/palak|palakura|green_curry|spinach|methi|poriyal|bhindi|salad|sprouts|tabbouleh|greek_salad|edamame|avial|som_tam/,'#6DAE4A'],[/dal|pappu|sambar|kadhi|lentil|misir|hummus/,'#E5B33D'],
    [/curry|kurma|masala|tikka|stew|tagine|wat|laksa|pav_bhaji/,'#D0742F'],[/curd|raita|yogurt|paneer|tofu|hung/,'#FAF8F2'],[/dosa|chapati|roti|paratha|naan|kulcha|puri|bhature|thepla|tortilla|pita|parotta|bread|bagel|croissant|toast|pancake|waffle|pav|injera|arepa|chilla|adai|uttapam|pesarattu|puran/,'#D9A35F'],
    [/egg|omelette|bhurji/,'#F6D365'],[/chicken|fish|salmon|steak|kebab|satay|bulgogi|sashimi|sushi/,'#E8946A'],[/potato|fries|aloo/,'#E9C46A']];
  for(const [re,c] of rules) if(re.test(id)||re.test(n)) return c;
  return {fruit:'#FF9F43',sweets:'#B8732F',snacks:'#D49A4E',grains:'#EFE6D2',breads:'#D9A35F',south:'#EADBB8',veg:'#6DAE4A',dairy:'#FAF8F2',curries:'#D0742F'}[f.cat]||'#D9C2A0';
}
const dishEls=new Map(); let cupId=null;
function renderDish(){
  const box=$('dishItems'); if(!box) return;
  const ex=expand(plate); // meals become their parts
  const foods=[], drinks=[], ghee=[];
  for(const [id,q] of ex){ const f=F[id]; if(!f) continue; if(/^ghee_/.test(id)&&!f.parts&&f.carbs===0) ghee.push([id,q]); else if(DRINK(id)) drinks.push([id,q]); else foods.push([id,q]); }
  const kcal=(f,q)=>(4*f.carbs+4*f.protein+9*f.fat+2*f.fiber)*q;
  foods.sort((a,b)=>kcal(F[b[0]],b[1])-kcal(F[a[0]],a[1]));
  const shown=foods.slice(0,7), extra=foods.length-shown.length;
  const C=76, RR=shown.length>4?46:44; // centre is the add button; food sits on a ring
  const pos=shown.map((_,i)=>{ const k=shown.length, a=-Math.PI/2+i*(2*Math.PI/k)+(k===2?Math.PI/2:0); return [C+Math.cos(a)*RR, C+Math.sin(a)*RR]; });
  const keep=new Set();
  shown.forEach(([id,q],i)=>{
    const f=F[id]; keep.add(id);
    let s=Math.max(28,Math.min(shown.length>5?40:shown.length>3?46:54, 24+Math.sqrt(kcal(f,Math.min(q,2)))*1.8)); if(SMALLSIDE.has(id)) s=Math.min(s,28);
    let el=dishEls.get(id);
    if(!el){ el=document.createElement('div'); el.className='mound new'; el.innerHTML='<span class="em"></span><span class="q"></span>'; box.appendChild(el); dishEls.set(id,el); el.addEventListener('animationend',()=>el.classList.remove('new'),{once:true}); }
    el.classList.remove('out'); el.style.background=`radial-gradient(circle at 38% 32%, color-mix(in srgb, ${moundColor(f)} 92%, #fff), color-mix(in srgb, ${moundColor(f)} 72%, #000))`;
    el.style.left=pos[i][0]+'px'; el.style.top=pos[i][1]+'px'; el.style.width=s+'px'; el.style.height=(s*0.9)+'px'; el.style.zIndex=2;
    el.querySelector('.em').textContent=f.emoji; el.querySelector('.em').style.fontSize=Math.round(s*0.5)+'px';
    const qq=el.querySelector('.q'); qq.textContent=q>1?fmtQ(q):''; qq.style.display=q>1?'':'none';
    el.title=`${f.name}${q!==1?' '+fmtQ(q):''}`;
  });
  // ghee dollop on top of the main item
  const gq=ghee.reduce((a,[id,q])=>a+q*(id==='ghee_tbsp'?3:1),0);
  let gel=dishEls.get('__ghee');
  if(gq>0 && shown.length){ keep.add('__ghee'); if(!gel){ gel=document.createElement('div'); gel.className='mound ghee new'; gel.innerHTML='<span class="q"></span>'; box.appendChild(gel); dishEls.set('__ghee',gel); gel.addEventListener('animationend',()=>gel.classList.remove('new'),{once:true}); }
    const gs=Math.min(30,12+gq*3); gel.classList.remove('out'); let gi=0; shown.forEach(([id,q],i)=>{ if(F[id].carbs*q>F[shown[gi][0]].carbs*shown[gi][1]) gi=i; }); gel.style.left=(pos[gi][0]+8)+'px'; gel.style.top=(pos[gi][1]-10)+'px'; gel.style.width=gs+'px'; gel.style.height=(gs*.85)+'px'; gel.title=`Ghee, ${gq} tsp`;
    const qq=gel.querySelector('.q'); qq.textContent=gq>1?gq+' tsp':''; qq.style.display=gq>1?'':'none'; }
  for(const [k,el] of dishEls){ if(!keep.has(k)){ el.classList.add('out'); dishEls.delete(k); setTimeout(()=>el.remove(),260); } }
  let more=box.querySelector('.more'); if(extra>0){ if(!more){ more=document.createElement('div'); more.className='more'; box.appendChild(more); } more.textContent='+'+extra+' more'; } else if(more) more.remove();
  $('dishAdd').classList.toggle('full',foods.length>0);
  // drinks in a cup beside the plate
  const cup=$('cup');
  if(drinks.length){ const [id,q]=drinks[0]; const total=drinks.reduce((a,d)=>a+d[1],0); if(cupId!==id){ cup.classList.remove('on'); void cup.offsetWidth; } cup.classList.add('on'); cupId=id; cup.innerHTML=`${F[id].emoji}${total>1||drinks.length>1?`<span class="q">${drinks.length>1?drinks.length+' drinks':fmtQ(total)}</span>`:''}`; cup.title=drinks.map(([d])=>F[d].name).join(', '); }
  else { cup.classList.remove('on'); cupId=null; }
}

/* ---------- home update ---------- */
function update(){
  const h=habits(), pr=predict(plate,prof,h);
  const ghost=(h.order||h.walk)&&plate.size?predict(plate,prof,NOH):null;
  const pk=Math.round(pr.peak);
  tweenNum($('peak'),pk);
  if(plate.size){ const st=settleText(pr); $('peakSub').textContent=`+${Math.round(pr.rise)} mg/dL, peaking around ${Math.round(pr.tp/5)*5} min. `+(st?`Settles in about ${st}.`:'Still elevated at 3 h.'); }
  else $('peakSub').textContent='Add food to see your curve';
  const sc=plate.size?scoreOf(plate,h):null;
  $('scoreN').textContent=sc??'-';
  const arc=$('ringArc'),C=232.5; arc.style.strokeDashoffset=sc?C*(1-sc/10):C; arc.style.stroke=!sc?'var(--chip)':sc>=7?'var(--green)':sc>=4?'var(--amber)':'var(--red)';
  const z=$('zone'); if(!plate.size){ z.innerHTML='&nbsp;'; z.style.color=''; } else { z.textContent=zoneText(prof,pk); z.style.color=colFor(pk,prof); }
  drawChart($('chart'),pr,ghost,prof,'g-home');
  renderPlate(pr); renderFoods(); renderSugg(pr); renderDish();
  $('fabN').textContent=[...plate.values()].reduce((a,b)=>a+b,0); $('fabPk').textContent=pk;
  fabVis(); save();
}

/* ---------- detail page ---------- */
const TIPS = {
  ghee:['🧈','About ghee','Ghee has no carbohydrate, so it doesn\'t raise glucose by itself. Its fat slows digestion, which lowers and delays the peak a little, but glucose can stay raised for longer. It isn\'t a fix for a big portion of rice: a teaspoon or two changes the curve far less than halving the rice or adding dal and vegetables. Ghee is also calorie-dense and high in saturated fat, so keep it to a teaspoon or two per meal, especially if you watch your weight or cholesterol.'],
  usda:['🇺🇸','About this USDA entry','Its carbohydrate, fibre, protein, and fat come from the USDA National Nutrient Database (Standard Reference), which is public domain. USDA does not publish GI, so we assigned one using food-group rules (for example, white bread 75, pasta 49, lentils 30), similar to how researchers add GI to large nutrient databases. Treat the curve as a rough guide.'],
  asia:['🥢','About East and Southeast Asian food','Jasmine and sticky rice are among the fastest-digesting rices tested, while soba and egg noodles are gentler. Broths, tofu, edamame, and vegetables on the side slow the meal down.'],
  western:['🍝','About American and European food','Pasta cooked al dente has a surprisingly moderate GI, while mashed and baked potatoes and white baguette sit near the top. Sweet breakfasts like pancakes with syrup usually spike more than eggs-based ones.'],
  medit:['🫒','About Mediterranean and Middle Eastern food','Legume-based dishes such as hummus, falafel, and lentils keep spikes low. Bread, rice, and couscous carry most of the load, so balance them with the dips and salads.'],
  latin:['🌮','About Latin American food','Beans are a quiet strength of this cuisine: high in fibre and slow to digest. Corn tortillas tend to be gentler than nachos or fried churros.'],
  africa:['🌍','About African food','Starchy swallows like fufu and ugali digest quickly. The stews served with them, rich in protein, fat, and legumes, are what slow the meal down, so eat them generously.'],
  coffee:['☕','About coffee','Coffee itself has almost no carbohydrate; the sugar and milk carry it. In some studies caffeine briefly made the body less sensitive to insulin, so a sweet coffee alongside a rice-based breakfast may peak a little higher than shown here. Cutting sugar gradually, about half a teaspoon less each week, is easy to get used to.'],
  grains:['🍚','About rice and grains','Rice that is cooked, cooled, and reheated forms some resistant starch, which may lower the spike modestly. Portion still matters most. If you take insulin or sulfonylurea tablets, talk to your doctor before relying on swaps like these, because a smaller spike can mean you need a lower dose.'],
  south:['🫓','About South Indian breakfasts','Fermented rice batters still digest quickly: Indian studies place plain dosa and idli in the high GI range. The sambar and chutney beside them matter. They add fibre, protein, and fat that slow the whole plate down, so don\'t skip them.'],
  breads:['🍞','About breads','Whole wheat bread spikes almost as much as white (GI about 71 vs 75). Flours with more fibre and protein, like besan blends and multigrain, change the curve more than the colour of the bread does.'],
  fruit:['🍎','About fruit','Whole fruit beats juice because the fibre stays intact. Riper fruit carries more sugar. Pairing fruit with nuts or curd softens the rise.'],
  sweets:['🍮','About sweets','A small sweet right after a balanced meal spikes less than the same sweet on an empty stomach, because the meal\'s fibre and protein are already slowing digestion. Portion is the strongest lever.'],
  drinks:['🥤','About drinks','Liquid sugar reaches the blood fastest. If a drink is sweet, have it with food rather than on its own, and choose smaller sizes.'],
  snacks:['🥟','About snacks','Fried snacks often spike later rather than lower, because fat delays digestion. Watch the curve\'s tail, not just its peak.'],
  curries:['🍲','About dal and curries','Dals, curries, and protein dishes are the brakes of a meal. Eat them first and the carbs that follow rise more gently.'],
  veg:['🥗','About vegetables','Non-starchy vegetables barely move glucose and slow everything eaten after them. Potatoes are the exception and behave more like rice.'],
  dairy:['🥛','About dairy and eggs','Curd, milk, paneer, and eggs bring protein and fat that keep spikes small. Sweetened versions are a different story.'],
  breakfast:['🌅','About breakfast','Many people see their highest spike of the day after breakfast. A breakfast led by protein and fibre tends to keep glucose steadier.'],
  meals:['🍽','About mixed meals','In a mixed meal, the order you eat things matters. Start with the vegetables, dal, or curry, and finish with the rice or bread.']
};
function tipFor(f){ if(f.src==='U') return TIPS.usda; const ids=f.parts?f.parts.map(p=>p[0]):[f.id]; if(ids.some(i=>/^ghee_(tsp|tbsp)$/.test(i))||/^ghee_/.test(f.id)) return TIPS.ghee; if(ids.some(i=>/coffee|cappuccino/.test(i))) return TIPS.coffee; return TIPS[f.cat]||TIPS.meals; }

let currentDetail=null, storySteps=[], storyObs=null, homeScroll=0, cameFromHome=false;
function buildSteps(f){
  const pk=prof, steps=[]; let p=f.parts?new Map(f.parts.map(([id,q])=>[id,q])):new Map([[f.id,1]]); let h={order:false,walk:false};
  const pr0=predict(p,pk,h); steps.push({icon:f.emoji,title:'As it is',text:`${escapeHTML(f.name)} delivers about ${Math.round(pr0.n.carbs)} g of carbohydrate at a ${f.parts?'combined ':''}GI of ${Math.round(pr0.n.gi)}.`,pr:pr0,delta:0});
  const push=(icon,title,text,np,nh,extra)=>{ const pr=predict(np,pk,nh), prev=steps[steps.length-1].pr; const d=prev.peak-pr.peak; if(d>=2.5){ steps.push({icon,title,text,pr,delta:d,extra}); p=np; h=nh; return true; } return false; };
  const n0=nutr(p);
  if(n0.carbs>=15 && f.cat!=='drinks'){
    const hasVeg=[...p.keys()].some(id=>!/^(ghee_tsp|ghee_tbsp|pickle|papad|podi)$/.test(id)&&['veg','curries','dairy'].includes(F[id].cat)||['sambar','rasam','kadala_curry','veg_kurma','veg_stew','avial','coco_chutney','tomato_chutney'].includes(id));
    if(hasVeg) push('🔁','Eat the sides first','Start with the '+[...p.keys()].filter(id=>!['grains','breads','south','breakfast','snacks','sweets','drinks','fruit'].includes(F[id].cat)||['sambar','rasam','kadala_curry','veg_kurma','veg_stew','avial','coco_chutney'].includes(id)).filter(id=>!/^(ghee_tsp|ghee_tbsp|pickle|papad|podi)$/.test(id)).map(id=>F[id].name.toLowerCase()).slice(0,2).join(' and ')+', and finish with the carbs. Same food, gentler curve.',p,{...h,order:true});
    else push('🥗','Start with a bowl of salad','Eat a bowl of salad, such as kachumber or mixed greens, before the rest. The fibre arrives first and slows everything that follows.',plateWith(p,m=>m.set('salad',1)),{...h,order:true});
  }
  // swap the biggest-GL component
  const comps=[...p].filter(([id])=>F[id].carbs>0).map(([id,q])=>({id,q,gl:F[id].gi*F[id].carbs*q/100})).sort((a,b)=>b.gl-a.gl);
  { let best=null;
    for(const c of comps.slice(0,3)){
      let ex=F[c.id].alts.filter(x=>F[x]); if(!ex.length) ex=swapsFor(c.id); const real=ex.filter(x=>F[x].carbs>=F[c.id].carbs*0.35); if(real.length) ex=real;
      for(const alt of ex){ if(p.has(alt)) continue; const np=plateWith(p,m=>{m.delete(c.id);m.set(alt,c.q);}); const pr=predict(np,pk,h); if(!best||pr.peak<best.pr.peak) best={from:c.id,alt,np,pr}; }
    }
    if(best) push('🔄',`Swap ${F[best.from].name.toLowerCase()} for ${F[best.alt].name.toLowerCase()}`,whySwap(F[best.from],F[best.alt]),best.np,h,{from:best.from,to:best.alt});
  }
  // add a protein/fibre partner
  if(nutr(p).carbs>=12){ let best=null; const WORLD=new Set(['asia','western','medit','latin','africa']); const isWorld=WORLD.has(f.cat)||(f.parts&&f.parts.some(([x])=>WORLD.has(F[x].cat))); for(const id of (isWorld?['eggs','grilled_chicken','almonds','hung_curd','edamame','salad']:ADDONS)){ if(p.has(id)) continue; const np=plateWith(p,m=>m.set(id,1)); const pr=predict(np,pk,h); if(!best||pr.peak<best.pr.peak) best={id,np,pr}; }
    if(best) push(F[best.id].emoji,`Add ${F[best.id].name.toLowerCase()}`,whyAdd(F[best.id]),best.np,h); }
  // right-size the biggest carb
  const big=[...p].map(([id,q])=>({id,q,c:F[id].carbs*q})).sort((a,b)=>b.c-a.c)[0];
  if(big && big.c>=25){ const nq=Math.max(0.5,Math.round(big.q*0.75*2)/2>=big.q?big.q-0.5:Math.round(big.q*0.75*2)/2); if(nq>0&&nq<big.q) push('⚖️',`Have ${nq===big.q/2?'half':'a smaller portion of'} the ${F[big.id].name.toLowerCase()}`,`That removes about ${Math.round(big.c-F[big.id].carbs*nq)} g of carbs. Fill the space with vegetables or dal.`,plateWith(p,m=>m.set(big.id,nq)),h); }
  if(nutr(p).carbs>=12) push('🚶','Walk 10 to 15 minutes after','Start within half an hour of eating. Working muscles pull glucose from the blood as it arrives, no gym needed.',p,{...h,walk:true});
  return {steps, finalPlate:p, finalHabits:h};
}
function renderDetail(id, keepScroll){
  const f=F[id]; if(!f){ location.hash='#home'; return; }
  currentDetail=id;
  const p=new Map([[id,1]]), pr=predict(p,prof,NOH);
  document.title=`${f.name} · Spike Lab`;
  $('dEmoji').textContent=f.emoji; $('dCrumb').textContent=f.src==='U'?'USDA database · '+USDA_GROUPS[f.grp][0]:CATNAME[f.cat]; $('dTitle').textContent=f.name; $('dServ').textContent=`${f.serving}${f.parts?', '+f.parts.length+' parts':''}`;
  $('dTags').innerHTML=[`<span class="d-tag">${SRC[f.src]}</span>`,`<span class="d-tag">Score ${f._score}/10</span>`,f.carbs<10?'<span class="d-tag">Low carb</span>':''].join('');
  const pk=Math.round(pr.peak);
  tweenNum($('dPeak'),pk); $('dRise').textContent=pr.rise>1?`+${Math.round(pr.rise)} mg/dL, peaking around ${Math.round(pr.tp/5)*5} min`:'Barely moves glucose';
  $('dZone').textContent=zoneText(prof,pk); $('dZone').style.color=colFor(pk,prof);
  const sc=scoreOf(p,NOH); const arc=$('dArc'),C=207.3; arc.style.strokeDashoffset=C*(1-sc/10); arc.style.stroke=sc>=7?'var(--green)':sc>=4?'var(--amber)':'var(--red)'; $('dScore').textContent=sc;
  drawChart($('dChart'),pr,null,prof,'g-det');
  const n=pr.n;
  $('dNums').innerHTML=[['Carbs',Math.round(n.carbs),'g'],['GI',Math.round(n.gi),f.src==='E'?'est.':''],['Glycaemic load',Math.round(n.gl),''],['Fibre',Math.round(n.fiber),'g'],['Protein',Math.round(n.protein),'g'],['Fat',Math.round(n.fat),'g']].map(([k,v,u])=>`<div><span>${k}</span><b>${v}<small>${u}</small></b></div>`).join('');
  const st=settleText(pr);
  $('dVerdict').textContent = pr.rise<15 ? `A steady choice. ${f.name} barely moves glucose on its own.` : `${f.name} raises glucose by about ${Math.round(pr.rise)} mg/dL for the ${prof==='none'?'no diabetes':prof==='pre'?'prediabetes':'type 2'} profile${st?`, settling in about ${st}`:', and stays elevated past 3 hours'}.`;
  $('dAdd').dataset.add=id;
  // parts
  if(f.parts){ $('dParts').hidden=false;
    const tot=f.parts.reduce((a,[pid,q])=>a+F[pid].gi*F[pid].carbs*q,0)||1;
    $('dPartList').innerHTML=f.parts.map(([pid,q])=>{ const g=F[pid], share=g.gi*g.carbs*q/tot*100; return `<a class="prow" href="${link(pid)}"><span class="e" aria-hidden="true">${g.emoji}</span><span class="n">${escapeHTML(g.name)}<small>${q===1?'':fmtQ(q)+' '}${escapeHTML(g.serving)} · ${Math.round(g.carbs*q)} g carbs · GI ${g.gi}</small></span><span class="pbar" aria-hidden="true"><i style="width:${Math.max(2,share)}%"></i></span><span class="pct">${Math.round(share)}%</span></a>`; }).join('');
  } else $('dParts').hidden=true;
  // story
  const {steps,finalPlate,finalHabits}=buildSteps(f); storySteps=steps;
  const total=steps[0].pr.peak-steps[steps.length-1].pr.peak;
  if(steps.length<2 || total<5){
    $('storyGrid').hidden=true; $('finale').hidden=true; $('steadyMsg').hidden=false;
    $('storyH').textContent='Already steady.'; $('storySub').textContent=`${f.name} is one of the gentler choices. Here's how to keep it that way.`;
    $('steadyMsg').innerHTML=`<p>Its predicted peak is ${pk} mg/dL, and none of our swaps or habits moves it by more than a few points. Keep the portion sensible, and pair it with vegetables or protein when it's part of a bigger meal.</p>`;
  } else {
    $('storyGrid').hidden=false; $('finale').hidden=false; $('steadyMsg').hidden=true;
    $('storyH').textContent='Make it steadier.'; $('storySub').textContent=`Scroll through ${steps.length-1} small changes. Each one builds on the last.`;
    $('stepList').innerHTML=steps.map((s,i)=>`<div class="stp" data-i="${i}"><div class="stp-card"><div class="stp-n">${i===0?'Start':'Step '+i}</div>${s.extra?`<div class="swaprow"><span class="x">${F[s.extra.from].emoji}</span><span style="font-size:1.1rem;opacity:.5">→</span><span>${F[s.extra.to].emoji}</span></div>`:`<div class="stp-ic">${s.icon}</div>`}<h3>${escapeHTML(s.title)}</h3><p>${s.text}</p>${i?`<div class="gain">−${Math.round(s.delta)}<small>mg/dL from the peak</small></div>`:`<div class="gain" style="color:#fff">${Math.round(s.pr.peak)}<small>mg/dL predicted peak</small></div>`}</div></div>`).join('');
    $('dots').innerHTML=steps.map(()=>'<i></i>').join('');
    const last=steps[steps.length-1];
    $('finaleNums').innerHTML=`<s>${Math.round(steps[0].pr.peak)}</s> → <span>${Math.round(last.pr.peak)}</span>`;
    $('finaleText').textContent=`Together, these changes lower the predicted peak by about ${Math.round(total)} mg/dL. You don't need all of them. Even one or two make a visible difference.`;
    $('applyAll').onclick=()=>{ for(const [pid,q] of finalPlate) plate.set(pid,(plate.get(pid)||0)+q); $('order').checked=finalHabits.order; $('walk').checked=finalHabits.walk; update(); toast('Steadier version added to your plate'); };
    setStep(0);
    if(storyObs) storyObs.disconnect();
    storyObs=new IntersectionObserver(es=>{ es.forEach(e=>{ if(e.isIntersecting) setStep(+e.target.dataset.i); }); },{rootMargin:'-45% 0px -45% 0px'});
    document.querySelectorAll('.stp').forEach(el=>storyObs.observe(el));
  }
  // tip
  const [ic,tt,tx]=tipFor(f); $('tipIc').textContent=ic; $('tipH').textContent=tt; $('tipP').textContent=tx;
  // similar
  const sim=FOODS.filter(g=>g.cat===f.cat&&(f.cat!=='usda'||g.grp===f.grp)&&g.id!==id).sort((a,b)=>Math.abs(a.carbs-f.carbs)-Math.abs(b.carbs-f.carbs)).slice(0,10).sort((a,b)=>a._peak-b._peak);
  $('simList').innerHTML=sim.map(card).join('');
  $('simH').textContent=`More ${(f.src==='U'?USDA_GROUPS[f.grp][0]:CATNAME[f.cat]).toLowerCase()}`;
  renderMeasured(id);
  if(!keepScroll) window.scrollTo(0,0);
}
function setStep(i){
  const s=storySteps[i]; if(!s) return;
  document.querySelectorAll('.stp').forEach(el=>el.classList.toggle('on',+el.dataset.i===i));
  drawChart($('sChart'),s.pr,i?storySteps[0].pr:null,prof,'g-story','as it is');
  $('sPeak').innerHTML=`${Math.round(s.pr.peak)}<small>mg/dL peak</small>`; $('sPeak').style.color=colFor(s.pr.peak,prof);
  $('sFrom').innerHTML=i?`from <b>${Math.round(storySteps[0].pr.peak)}</b>, now −${Math.round(storySteps[0].pr.peak-s.pr.peak)}`:'starting point';
  $('sName').textContent=i?s.title:'As it is';
  [...$('dots').children].forEach((d,k)=>d.classList.toggle('on',k<=i));
}

/* ---------- router ---------- */
function route(){
  const h=location.hash;
  if(h.startsWith('#food/')){
    if(!$('home').hidden){ homeScroll=window.scrollY; cameFromHome=true; }
    $('home').hidden=true; $('detail').hidden=false; renderDetail(decodeURIComponent(h.slice(6)));
  } else {
    const wasDetail=!$('detail').hidden;
    $('detail').hidden=true; $('home').hidden=false; currentDetail=null; document.title='Spike Lab by mytr.ai';
    if(storyObs){ storyObs.disconnect(); storyObs=null; }
    update();
    const el=h&&h.length>1?document.getElementById(h.slice(1)):null;
    if(el) el.scrollIntoView(); else if(wasDetail) window.scrollTo(0,homeScroll);
  }
}
window.addEventListener('hashchange',route);
$('back').addEventListener('click',()=>{ if(cameFromHome) history.back(); else location.hash='#home'; });

/* ---------- fab, toast, dialog ---------- */
let panelVisible=true;
new IntersectionObserver(es=>{ panelVisible=es[0].isIntersecting; fabVis(); },{threshold:.15}).observe($('panel'));
function fabVis(){ const show=plate.size>0 && (!panelVisible || !$('detail').hidden); $('fab').classList.toggle('show',show); $('fab').setAttribute('aria-hidden',!show); }
$('fabGo').addEventListener('click',()=>{ if(!$('detail').hidden){ location.hash='#build'; } else $('panel').scrollIntoView({block:'start'}); });
let tt; function toast(m){ const t=$('toast'); t.textContent=m; t.classList.add('show'); clearTimeout(tt); tt=setTimeout(()=>t.classList.remove('show'),1700); }
$('openData').addEventListener('click',()=>{
  const data={name:'mytr.ai Spike Lab dataset',licence:'MIT',version:'2.0',units:{carbs:'g available carbohydrate per serving',fibre:'g',protein:'g',fat:'g'},giSource:{T:'international GI tables (Atkinson 2008/2021)',I:'Indian GI studies',E:'estimated from ingredients and recipe',C:'computed from parts'},
    foods:FOODS.filter(f=>!f.parts&&f.src!=='U').map(f=>({id:f.id,name:f.name,category:f.cat,serving:f.serving,carbs:f.carbs,fibre:f.fiber,protein:f.protein,fat:f.fat,gi:f.gi,giSource:f.src,swaps:f.alts})),
    usdaNote:'The ~8,800 USDA entries (public domain, SR28) are bundled in this page as USDA=[ndb_no,name,group,serving,availableCarbs,fibre,protein,fat,gi]; GI there is rule-based.',
    meals:FOODS.filter(f=>f.parts).map(f=>({id:f.id,name:f.name,parts:f.parts.map(([id,q])=>({id,servings:q}))}))};
  $('dataTxt').value=JSON.stringify(data,null,2); $('dlg').showModal();
});
$('dlgClose').addEventListener('click',()=>$('dlg').close());
$('dlg').addEventListener('click',e=>{ if(e.target===$('dlg')) $('dlg').close(); });
$('copy').addEventListener('click',async()=>{ const ta=$('dataTxt'); try{ await navigator.clipboard.writeText(ta.value); toast('Dataset copied'); }catch(e){ ta.focus(); ta.select(); try{ document.execCommand('copy'); toast('Dataset copied'); }catch(_){ toast('Select all and copy'); } } });


/* =========================================================
   PUBLIC API + PLUGINS
   ========================================================= */
CATNAME.custom='Detected foods'; CATNAME.community='Community foods';
const detectors=[];
function refreshDetPick(){
  const sel=$('detPick'); sel.innerHTML=detectors.map(d=>`<option value="${escapeHTML(d.id)}">${escapeHTML(d.name)}</option>`).join('');
  $('detPickWrap').hidden=detectors.length<2;
}
const SpikeLab = Object.freeze({
  version:'1.0',
  foods:(q='')=>{ const t=String(q).toLowerCase().split(/\s+/).filter(Boolean); return FOODS.filter(f=>matches(f,t)).slice(0,50).map(f=>({id:f.id,name:f.name,serving:f.serving,carbs:+f.carbs.toFixed(1),gi:Math.round(f.gi),source:f.src})); },
  predict:(items,profile='none',hab={})=>{ const p=new Map(Object.entries(items||{}).filter(([id])=>F[id]).map(([id,q])=>[id,Number(q)||1])); const pr=predict(p,PROF[profile]?profile:'none',{order:!!hab.order,walk:!!hab.walk}); return {peak:Math.round(pr.peak),rise:Math.round(pr.rise),timeToPeak:Math.round(pr.tp),carbs:Math.round(pr.n.carbs),gi:Math.round(pr.n.gi),gl:Math.round(pr.n.gl)}; },
  steadier:(id)=>{ const f=F[id]; if(!f) return null; return buildSteps(f).steps.map(s=>({step:s.title,peak:Math.round(s.pr.peak)})); },
  registerDetector:(d)=>{ if(!d||typeof d.detect!=='function'||!d.id) throw new TypeError('registerDetector needs {id, name, detect(file)}'); const i=detectors.findIndex(x=>x.id===d.id); const entry={id:String(d.id),name:String(d.name||d.id),detect:d.detect}; if(i>=0) detectors[i]=entry; else detectors.push(entry); refreshDetPick(); return true; }
});
window.SpikeLab = SpikeLab;

/* =========================================================
   MEAL DETECTOR
   ========================================================= */
let snap=new Map(), snapTitle='Your meal', snapCtl=null, customN=0;
const CATALOG = FOODS.filter(f=>!f.parts && f.src!=='U' && f.src!=='M').map(f=>`${f.id}|${f.name}|${f.serving}`).join('\n');
async function claudeDetect(file, signal){
  const sample = await window.claude.use('sample');
  const prompt = `You are an experienced dietitian looking at a photo of a meal.
Identify every food and drink you can see. For each one:
- If an item in the CATALOG below is a good match, use its id and estimate "servings" relative to that catalog serving (0.5 steps).
- If nothing in the catalog matches well, set "id" to null and give its name, servings 1, and your best estimate per serving of available carbs, fibre, protein and fat in grams, plus an estimated glycaemic index.
- Give each item a confidence from 0 to 1.
Reply with only JSON in this shape:
{"title":"short name for the meal","items":[{"id":"masala_dosa","name":"Masala dosa","servings":1,"confidence":0.9}],"notes":"one short sentence"}
If the photo shows no food, reply {"title":"","items":[],"notes":"No food found."}

CATALOG (id|name|serving):
${CATALOG}`;
  return await sample.json(prompt,{images:file,signal,cache:false});
}
let detState='checking', detReason='';
const detReady=(async()=>{
  try{
    if(!window.claude||!window.claude.use){ detState='none'; detReason='This copy of Spike Lab is not running inside claude.ai, so the built-in detector is off. A self-hosted detector plugin can be added.'; return; }
    const sample=await window.claude.use('sample');
    if(!sample){ detState='none'; detReason='Claude is not available to this page in this view. Open Spike Lab in claude.ai on the web while signed in.'; return; }
    const lim=await sample.limits().catch(()=>null);
    if(!lim||!lim.images){ detState='none'; detReason='This Claude view can\'t send photos to the detector. Try claude.ai in a desktop or mobile browser.'; return; }
    SpikeLab.registerDetector({id:'claude',name:'Claude vision (built in)',detect:claudeDetect});
    detState='ready';
  }catch(e){ detState='none'; detReason='The detector could not start.'; }
  finally{ if(!$('snapImg').src) setStatus(detState==='ready'?'Detector ready. Take or upload a photo of your meal.':escapeHTML(detReason)); }
})();
async function setupClaudeDetector(){ return detReady; }
async function toJpeg(file){
  const MAX=1600;
  let src=null, w=0, h=0;
  try{ src=await createImageBitmap(file); w=src.width; h=src.height; }
  catch(e){
    src=await new Promise((res,rej)=>{ const im=new Image(); im.onload=()=>res(im); im.onerror=()=>rej(new Error('decode')); im.src=URL.createObjectURL(file); });
    w=src.naturalWidth; h=src.naturalHeight;
  }
  const k=Math.min(1,MAX/Math.max(w,h)); const c=document.createElement('canvas'); c.width=Math.round(w*k); c.height=Math.round(h*k);
  c.getContext('2d').drawImage(src,0,0,c.width,c.height);
  return await new Promise((res,rej)=>c.toBlob(b=>b?res(b):rej(new Error('encode')),'image/jpeg',0.85));
}
function setStatus(html){ $('snapStatus').innerHTML=html; }
async function runDetect(file){
  if(!file) return;
  const isImg=/^image\//.test(file.type)||/\.(heic|heif|jpe?g|png|webp)$/i.test(file.name||'');
  if(!isImg){ setStatus('That file is not an image. Try a JPEG, PNG or WebP photo.'); return; }
  let jpg;
  try{ jpg=await toJpeg(file); }
  catch(e){ setStatus(/heic|heif/i.test(file.type+file.name)?'This photo is in HEIC format, which this browser can\'t open. Use "Take a photo", or set your iPhone camera to Most Compatible (Settings › Camera › Formats).':'That image couldn\'t be opened. Try another photo.'); return; }
  const img=$('snapImg'); img.src=URL.createObjectURL(jpg); img.hidden=false; $('dropInner').hidden=true;
  if(detState==='checking'){ setStatus('<span class="spin"></span>Starting the detector…'); await detReady; }
  const det=detectors.find(d=>d.id===$('detPick').value)||detectors[0];
  if(!det){ setStatus(escapeHTML(detReason||'No detector is available in this view.')+' You can still build the meal in the plate builder.'); return; }
  snapCtl?.abort(); snapCtl=new AbortController(); const ctl=snapCtl;
  setStatus(`<span class="spin"></span>Looking at your plate with ${escapeHTML(det.name)}. The first time, claude.ai asks you to allow it. <button class="linkbtn" id="snapStop" type="button">Stop</button>`);
  $('snapStop').onclick=()=>ctl.abort();
  try{
    const res=await det.detect(jpg,ctl.signal);
    if(ctl.signal.aborted) return;
    applyDetection(res);
  }catch(e){
    const c=(e&&e.code)||'upstream_error';
    const msg={cancelled:'Stopped.',not_granted:'The detector was not allowed. Reload the page and choose Allow when claude.ai asks, to use it.',sampling_disabled:'Claude isn\'t available for this account or organisation.',images_unavailable:'This Claude view can\'t send photos. Try claude.ai in a browser.',rate_limited:'You\'ve hit a usage limit for now. Try again in a little while.',image_rejected:'That image couldn\'t be read. Try another photo.',refused:'The detector couldn\'t analyse this photo. Try a clearer photo of the food.',invalid_json:'The detector replied in an unexpected format. Try again.',session_expired:'Your claude.ai session expired. Sign in again and reload.'}[c]||'Something went wrong while detecting. Try again.';
    setStatus(escapeHTML(msg)+(c!=='cancelled'?` <span class="hint">(code: ${escapeHTML(c)})</span>`:''));
  }
}
function applyDetection(res){
  const items=Array.isArray(res&&res.items)?res.items.slice(0,15):[];
  snap=new Map(); let unknown=0;
  for(const it of items){
    const sv=Math.max(0.5,Math.min(6,Math.round((Number(it.servings)||1)*2)/2));
    const conf=Math.max(0,Math.min(1,Number(it.confidence)||0));
    if(it.id&&F[String(it.id)]){ snap.set(String(it.id),{q:sv,conf}); continue; }
    const name=String(it.name||'').slice(0,60); if(!name) continue;
    const num=(v,m)=>Math.max(0,Math.min(m,Number(v)||0));
    const id='custom_'+(++customN);
    F[id]={id,name,emoji:'🍽',cat:'custom',serving:'1 serving (estimated)',carbs:num(it.carbs,200),fiber:num(it.fibre??it.fiber,60),protein:num(it.protein,120),fat:num(it.fat,120),gi:num(it.gi,110)||55,src:'E',alts:[]};
    snap.set(id,{q:sv,conf}); unknown++;
  }
  snapTitle=String(res&&res.title||'Your meal').slice(0,60)||'Your meal';
  if(!snap.size){ setStatus(escapeHTML(String(res&&res.notes||'No food found in this photo.'))); $('snapRes').hidden=true; $('snapEmpty').hidden=false; return; }
  setStatus(`Found ${snap.size} item${snap.size>1?'s':''}${unknown?`, ${unknown} estimated from the photo`:''}. Adjust anything that looks wrong.`);
  renderSnap();
}
function snapPlate(){ return new Map([...snap].map(([id,v])=>[id,v.q])); }
function renderSnap(){
  $('snapEmpty').hidden=true; $('snapRes').hidden=false;
  $('snapTitle').textContent=snapTitle;
  $('snapItems').innerHTML=[...snap].map(([id,v])=>{ const f=F[id]; return `<li><span class="e" aria-hidden="true">${f.emoji}</span><span class="n">${escapeHTML(f.name)}${v.conf?`<span class="conf">${Math.round(v.conf*100)}%</span>`:''}<small>${escapeHTML(f.serving)} · ${Math.round(f.carbs*v.q)} g carbs</small></span>
    <span class="step"><button type="button" data-ss="${id}" data-d="-0.5" aria-label="Less">−</button><span>${fmtQ(v.q)}</span><button type="button" data-ss="${id}" data-d="0.5" aria-label="More">+</button></span><button class="rm" type="button" data-srm="${id}" aria-label="Remove ${escapeHTML(f.name)}">×</button></li>`; }).join('');
  const p=snapPlate(), pr=predict(p,prof,NOH), sc=scoreOf(p,NOH);
  tweenNum($('snapPeak'),pr.peak); $('snapPeak').style.color=colFor(pr.peak,prof);
  $('snapScore').className='score '+cls(sc); $('snapScore').textContent=sc+'/10';
  drawChart($('snapChart'),pr,null,prof,'g-snap');
  const meal={id:'snap_meal',name:snapTitle,emoji:'🍽',cat:'meals',parts:[...p]};
  const {steps,finalPlate,finalHabits}=buildSteps(meal);
  const last=steps[steps.length-1];
  $('snapBest').innerHTML = steps.length>1 && steps[0].pr.peak-last.pr.peak>=5
    ? `<h4>Steadier version: ${Math.round(steps[0].pr.peak)} → ${Math.round(last.pr.peak)} mg/dL</h4><ol>${steps.slice(1).map(s=>`<li>${escapeHTML(s.title)} <b>−${Math.round(s.delta)}</b></li>`).join('')}</ol>`
    : '<h4>Already a steady meal.</h4>';
  $('snapAddBest').hidden = !(steps.length>1);
  $('snapAddBest').onclick=()=>{ for(const [id,q] of finalPlate) plate.set(id,(plate.get(id)||0)+q); $('order').checked=finalHabits.order; $('walk').checked=finalHabits.walk; update(); toast('Steadier version added to your plate'); };
}
$('snapItems').addEventListener('click',e=>{
  const b=e.target.closest('[data-ss]'); const r=e.target.closest('[data-srm]');
  if(b){ const v=snap.get(b.dataset.ss); v.q=Math.max(0.5,v.q+(+b.dataset.d)); renderSnap(); }
  if(r){ snap.delete(r.dataset.srm); if(snap.size) renderSnap(); else { $('snapRes').hidden=true; $('snapEmpty').hidden=false; } }
});
$('snapAdd').addEventListener('click',()=>{ for(const [id,v] of snap) plate.set(id,(plate.get(id)||0)+v.q); update(); toast('Meal added to your plate'); });
['camIn','upIn'].forEach(id=>$(id).addEventListener('change',e=>{ runDetect(e.target.files[0]); e.target.value=''; }));
const drop=$('drop');
['dragenter','dragover'].forEach(ev=>drop.addEventListener(ev,e=>{ e.preventDefault(); drop.classList.add('over'); }));
['dragleave','drop'].forEach(ev=>drop.addEventListener(ev,e=>{ e.preventDefault(); drop.classList.remove('over'); }));
drop.addEventListener('drop',e=>{ const f=e.dataTransfer.files&&e.dataTransfer.files[0]; if(f) runDetect(f); });


/* =========================================================
   COMMUNITY (db capability; storage adapter in the repo for self-hosting)
   ========================================================= */
SRC.M='Community submitted, source cited';
let cdb=null, cuid=null, cOwner=false, cCanWrite=null;
let cFoodsAll=[], cReads=[], cVotes={}, cMyVotes={}, cApproved={}, myFoods=[], myReads=[];
const injected=new Set();
const sNum=(v,a,b)=>{ if(v==null||v==='') return null; const n=Number(v); return Number.isFinite(n)?Math.max(a,Math.min(b,n)):null; };
const sStr=(v,m)=>typeof v==='string'?v.slice(0,m):'';
function cleanFood(it){ if(!it||typeof it!=='object') return null; const name=sStr(it.name,80).trim(); if(!name) return null;
  return {sid:sStr(it.sid,40),name,cuisine:sStr(it.cuisine,20),serving:sStr(it.serving,40),carbs:sNum(it.carbs,0,250)??0,fibre:sNum(it.fibre,0,80)??0,protein:sNum(it.protein,0,150)??0,fat:sNum(it.fat,0,150)??0,gi:sNum(it.gi,0,110),source:sStr(it.source,200),at:sNum(it.at,0,1e14)??0}; }
function cleanRead(r){ if(!r||typeof r!=='object') return null; const fid=sStr(r.fid,80); const base=sNum(r.base,40,400), peak=sNum(r.peak,40,500), tp=sNum(r.tp,5,240), sv=sNum(r.sv,0.5,5);
  if(!fid||base==null||peak==null||tp==null||sv==null) return null; return {fid,base,peak,tp,sv,prof:['none','pre','t2','t1'].includes(r.prof)?r.prof:'none',dev:sStr(r.dev,30),at:sNum(r.at,0,1e14)??0}; }
function cOffline(msg){ const n=$('cOffline'); n.hidden=false; n.textContent=msg; $('fFood').querySelectorAll('input,select,button').forEach(x=>x.disabled=true); $('fRead').querySelectorAll('input,select,button').forEach(x=>x.disabled=true); }
function syncInjected(){
  for(const id of injected){ const i=FOODS.findIndex(f=>f.id===id); if(i>=0) FOODS.splice(i,1); delete F[id]; }
  injected.clear();
  for(const c of cFoodsAll){ if(!cApproved[c.key]) continue; const id='c_'+c.key.replace(/[^a-zA-Z0-9]/g,'_').slice(0,60);
    const f={id,name:c.name,emoji:'🧑‍🍳',cat:CATNAME[c.cuisine]?c.cuisine:'snacks',serving:c.serving||'1 serving',carbs:c.carbs,fiber:c.fibre,protein:c.protein,fat:c.fat,gi:c.gi??55,src:'M',alts:[],cite:c.source};
    const p=new Map([[id,1]]); F[id]=f; f._score=scoreOf(p,NOH); f._peak=Math.round(predict(p,'none',NOH).peak); FOODS.push(f); injected.add(id); }
  renderFoods(); fillFoodList();
}
function fillFoodList(){ $('foodList').innerHTML=FOODS.filter(f=>f.src!=='U').map(f=>`<option value="${escapeHTML(f.name)}"></option>`).join(''); }
function renderCommunity(){
  const contributors=new Set([...cFoodsAll.map(c=>c.uid),...cReads.map(r=>r.uid)]);
  $('cContrib').textContent=contributors.size; $('cFoods').textContent=cFoodsAll.length; $('cReads').textContent=cReads.length;
  $('cVerified').textContent=cFoodsAll.filter(c=>cApproved[c.key]).length;
  const list=[...cFoodsAll].sort((a,b)=>((cVotes[b.key]||0)-(cVotes[a.key]||0))||(b.at-a.at)).slice(0,100);
  $('feed').innerHTML = list.length ? list.map(c=>{ const ok=!!cApproved[c.key], mine=c.uid===cuid, voted=!!cMyVotes[c.key];
    return `<div class="frow"><span class="n">${escapeHTML(c.name)}<small>${escapeHTML(c.serving)} · ${Math.round(c.carbs)} g carbs${c.gi!=null?' · GI '+Math.round(c.gi):''} · source: ${escapeHTML(c.source)}${mine?' · yours':''}</small></span>
      <span class="st ${ok?'ok':'pending'}">${ok?'Verified':'Pending'}</span>
      <span>${cOwner?`<button class="modbtn" type="button" data-mod="${escapeHTML(c.key)}">${ok?'Unverify':'Verify'}</button> `:''}<button class="vote" type="button" data-vote="${escapeHTML(c.key)}" aria-pressed="${voted}" ${cuid&&cCanWrite!==false?'':'disabled'}>▲ ${cVotes[c.key]||0}</button></span></div>`; }).join('')
    : '<p class="hint">Nothing submitted yet. Be the first.</p>';
  $('delMine').hidden=!(myFoods.length||myReads.length);
  if(currentDetail) renderMeasured(currentDetail);
}
function aggFor(fid){ const rs=cReads.filter(r=>r.fid===fid&&r.prof!=='t1'); if(!rs.length) return null; const pick=rs.filter(r=>r.prof===prof); const use=pick.length?pick:rs; const rise=use.reduce((a,r)=>a+(r.peak-r.base)/r.sv,0)/use.length; const tp=use.reduce((a,r)=>a+r.tp,0)/use.length; return {n:use.length,rise,tp,matched:pick.length>0}; }
function renderMeasured(id){
  const el=$('dMeasured'); if(!el) return; const a=aggFor(id);
  if(!a){ el.hidden=true; return; }
  const pr=predict(new Map([[id,1]]),prof,NOH);
  el.hidden=false; el.innerHTML=`📟 <b>Measured by the community:</b> average rise <b>+${Math.round(a.rise)} mg/dL</b> per serving, peaking around ${Math.round(a.tp)} min, from ${a.n} CGM reading${a.n>1?'s':''}${a.matched?'':' (all profiles)'}. Predicted: +${Math.round(pr.rise)}.`;
}
function subscribeAll(){
  const onErr=()=>{};
  cdb.collection('foods').onSnapshot(s=>{ cFoodsAll=[]; myFoods=[]; s.docs.forEach(d=>{ const items=(d.data()||{}).items; if(!Array.isArray(items)) return; items.slice(0,200).forEach(it=>{ const c=cleanFood(it); if(!c) return; c.uid=d.id; c.key=d.id+':'+c.sid; cFoodsAll.push(c); if(d.id===cuid) myFoods.push(it); }); }); syncInjected(); renderCommunity(); },onErr);
  cdb.collection('readings').onSnapshot(s=>{ cReads=[]; myReads=[]; s.docs.forEach(d=>{ const rs=(d.data()||{}).items; if(!Array.isArray(rs)) return; rs.slice(0,500).forEach(r=>{ const c=cleanRead(r); if(!c) return; c.uid=d.id; cReads.push(c); if(d.id===cuid) myReads.push(r); }); }); renderCommunity(); },onErr);
  cdb.collection('votes').onSnapshot(s=>{ cVotes={}; cMyVotes={}; s.docs.forEach(d=>{ const v=(d.data()||{}).v; if(!v||typeof v!=='object') return; for(const k of Object.keys(v).slice(0,500)){ if(v[k]){ cVotes[k]=(cVotes[k]||0)+1; if(d.id===cuid) cMyVotes[k]=1; } } }); renderCommunity(); },onErr);
  cdb.doc('moderation/approved').onSnapshot(d=>{ const ex=typeof d.exists==='function'?d.exists():d.exists; const k=(ex&&(d.data()||{}).keys)||{}; cApproved=typeof k==='object'?k:{}; syncInjected(); renderCommunity(); },onErr);
}
async function setupCommunity(){
  fillFoodList();
  // Self-hosted: provide window.SpikeLabStorage = {db, userId(), isOwner(), canWrite()} (see adapters/ in the repo)
  const ext=window.SpikeLabStorage;
  if(ext&&ext.db){
    cdb=ext.db; cuid=ext.userId?await ext.userId():null; cOwner=ext.isOwner?!!(await ext.isOwner()):false; cCanWrite=ext.canWrite?await ext.canWrite():true;
    if(!cuid) cOffline('Sign in to share foods and readings. You can still browse community data.');
    subscribeAll(); return;
  }
  if(!window.claude||!window.claude.use){ cOffline('Community sharing runs when Spike Lab is opened in claude.ai, or in the self-hosted open-source version with its own database.'); return; }
  cdb=await window.claude.use('db');
  const user=await window.claude.use('user');
  if(!cdb){ cOffline('Sign in to claude.ai to see and share community data. The self-hosted version can use its own database.'); return; }
  cuid = user ? await user.id() : null;
  cOwner = user ? await user.isOwner().catch(()=>false) : false;
  cCanWrite = user ? await user.can('data.write').catch(()=>null) : null;
  if(!cuid || cCanWrite===false) cOffline('You can browse community data here. Sharing needs Contributor access to this page; ask the owner, or use the self-hosted version.');
  subscribeAll();
}
function fmsg(form,txt,ok){ const m=form.querySelector('.fmsg'); m.textContent=txt; m.className='fmsg '+(ok?'ok':'err'); }
$('fFood').addEventListener('submit',async e=>{
  e.preventDefault(); const fm=e.target; if(!cdb||!cuid) return;
  if(!fm.checkValidity()){ fmsg(fm,'Please fill in every field, including a source.',false); return; }
  const d=Object.fromEntries(new FormData(fm));
  const it={sid:Date.now().toString(36)+Math.random().toString(36).slice(2,6),name:d.name.trim(),cuisine:d.cuisine,serving:d.serving.trim(),carbs:+d.carbs,fibre:+d.fibre,protein:+d.protein,fat:+d.fat,gi:d.gi===''?null:+d.gi,source:d.source.trim(),at:Date.now()};
  if(myFoods.length>=200){ fmsg(fm,'You have reached 200 submissions. Thank you!',false); return; }
  try{ await cdb.doc('foods/'+cuid).set({items:[...myFoods,it]}); fm.reset(); fmsg(fm,'Submitted. It will appear in the database once verified.',true); }
  catch(err){ fmsg(fm,err&&err.code==='quota_exceeded'?'The community database is full right now.':'Could not submit. You may not have permission to share here.',false); }
});

/* =========================================================
   LIBREVIEW IMPORT (runs entirely in the browser)
   ========================================================= */
let lvRaw=null, lvSeries=[], lvLogged=[], lvEvents=[], lvUnit=1;
function csvRows(text){
  const firstLines=text.split(/\r?\n/).slice(0,4).join('\n');
  const delim=(firstLines.split(';').length>firstLines.split(',').length)?';':',';
  const rows=[]; let row=[], f='', q=false;
  for(let i=0;i<text.length;i++){ const c=text[i];
    if(q){ if(c==='"'){ if(text[i+1]==='"'){ f+='"'; i++; } else q=false; } else f+=c; continue; }
    if(c==='"') q=true; else if(c===delim){ row.push(f); f=''; } else if(c==='\n'||c==='\r'){ if(c==='\r'&&text[i+1]==='\n') i++; row.push(f); rows.push(row); row=[]; f=''; } else f+=c; }
  if(f!==''||row.length){ row.push(f); rows.push(row); }
  return rows;
}
function parseStamp(s,fmt){
  s=String(s||'').trim(); if(!s) return null;
  let m=s.match(/^(\d{4})[-\/.](\d{1,2})[-\/.](\d{1,2})[ T](\d{1,2}):(\d{2})(?::\d{2})?\s*(AM|PM)?$/i), y,mo,d;
  if(m){ y=+m[1]; mo=+m[2]; d=+m[3]; }
  else { m=s.match(/^(\d{1,2})[-\/.](\d{1,2})[-\/.](\d{2,4})[ T,]+(\d{1,2}):(\d{2})(?::\d{2})?\s*(AM|PM)?$/i); if(!m) return null;
    y=+m[3]; if(y<100) y+=2000; if(fmt==='mdy'){ mo=+m[1]; d=+m[2]; } else { d=+m[1]; mo=+m[2]; } }
  let h=+m[4]; const mi=+m[5], ap=m[6]; if(ap){ if(/pm/i.test(ap)&&h<12) h+=12; if(/am/i.test(ap)&&h===12) h=0; }
  if(mo<1||mo>12||d<1||d>31) return null;
  return new Date(y,mo-1,d,h,mi).getTime();
}
function guessFmt(stamps){
  for(const s of stamps.slice(0,3000)){ const m=String(s).match(/^(\d{1,2})[-\/.](\d{1,2})[-\/.]\d{2,4}/); if(!m) continue; if(+m[1]>12) return 'dmy'; if(+m[2]>12) return 'mdy'; }
  return 'dmy';
}
function lvParse(text){
  const rows=csvRows(text);
  const hi=rows.findIndex(r=>r.some(c=>/device timestamp/i.test(c)));
  if(hi<0) throw new Error('This does not look like a LibreView export. Look for a file with a "Device Timestamp" column.');
  const H=rows[hi].map(c=>c.trim().toLowerCase()); const col=re=>H.findIndex(h=>re.test(h));
  const cT=col(/device timestamp/), cType=col(/record type/), cHist=col(/historic glucose/), cScan=col(/scan glucose/),
        cFood=col(/non-numeric food/), cCarb=col(/carbohydrates \(grams\)/), cNote=col(/^notes?$/);
  lvUnit = (cHist>=0 && /mmol/.test(H[cHist])) ? 18 : 1;
  return {rows:rows.slice(hi+1), cT,cType,cHist,cScan,cFood,cCarb,cNote};
}
function lvBuild(){
  const P=lvRaw, fmt=$('lvFmt').value; const S=[], L=[];
  for(const r of P.rows){ const t=parseStamp(r[P.cT],fmt); if(t==null) continue;
    const hv=parseFloat(String(r[P.cHist]??'').replace(',','.')), sv=parseFloat(String(r[P.cScan]??'').replace(',','.'));
    const v=Number.isFinite(hv)?hv:Number.isFinite(sv)?sv:null;
    if(v!=null&&v>0) S.push({t,v:Math.round(v*lvUnit)});
    const food=P.cFood>=0?String(r[P.cFood]||'').trim():'', carb=P.cCarb>=0?parseFloat(r[P.cCarb]):NaN, note=P.cNote>=0?String(r[P.cNote]||'').trim():'';
    if(food||note||Number.isFinite(carb)) L.push({t,label:(food||note||(Number.isFinite(carb)?Math.round(carb)+' g carbs':'')).slice(0,60)});
  }
  S.sort((a,b)=>a.t-b.t); L.sort((a,b)=>a.t-b.t);
  lvSeries=S; lvLogged=L;
  if(!S.length){ $('lvStat').textContent='No glucose readings found in this file.'; $('lvBody').hidden=true; return; }
  const cutoff=S[S.length-1].t-60*864e5;
  const ev=[]; const near=(t,list,w)=>list.some(e=>Math.abs(e.t-t)<w);
  for(const l of L){ if(l.t<cutoff) continue; if(near(l.t,ev,45*6e4)) continue; ev.push({t:l.t,kind:'logged',label:l.label}); }
  // detected rises: a local low followed by a rise of 30+ mg/dL within 90 minutes
  for(let i=0;i<S.length;i++){ const p=S[i]; if(p.t<cutoff) continue;
    let isMin=true, maxAfter=-1;
    for(let j=i-1;j>=0&&S[j].t>=p.t-30*6e4;j--) if(S[j].v<p.v){ isMin=false; break; }
    if(!isMin) continue;
    for(let j=i+1;j<S.length&&S[j].t<=p.t+90*6e4;j++) if(S[j].v<p.v){ isMin=false; break; } else maxAfter=Math.max(maxAfter,S[j].v);
    if(!isMin||maxAfter-p.v<30) continue;
    if(near(p.t,ev,150*6e4)) continue;
    ev.push({t:p.t,kind:'rise',label:'Rise detected from your curve (time may be up to 15 min early)'});
  }
  lvEvents=ev.sort((a,b)=>b.t-a.t).slice(0,80).map(e=>({...e,...lvMeasure(e.t),inc:false,food:'',sv:1}));
  const fmtD=t=>new Date(t).toLocaleDateString(undefined,{day:'numeric',month:'short'});
  $('lvStat').textContent=`${S.length.toLocaleString()} readings, ${fmtD(S[0].t)} to ${fmtD(S[S.length-1].t)}. ${lvEvents.filter(e=>e.kind==='logged').length} logged meals, ${lvEvents.filter(e=>e.kind==='rise').length} detected rises.`;
  $('lvBody').hidden=false; lvRender();
}
function lvMeasure(T){
  const S=lvSeries, W=t=>S.filter(p=>p.t>=t[0]&&p.t<=t[1]);
  const pre=W([T-30*6e4,T+5*6e4]); const flags=[];
  if(!pre.length) return {base:null,peak:null,tp:null,flags:['no reading near the meal time']};
  const before=pre.filter(p=>p.t<=T); const b=(before.length?before[before.length-1]:pre[0]);
  const post=W([T+1,T+180*6e4]);
  if(post.length<4) return {base:b.v,peak:null,tp:null,flags:['not enough readings after the meal']};
  let pk=post[0]; for(const p of post) if(p.v>pk.v) pk=p;
  const win=W([T-15*6e4,T+180*6e4]); let gap=0; for(let i=1;i<win.length;i++) gap=Math.max(gap,win[i].t-win[i-1].t);
  if(gap>35*6e4) flags.push('gaps in the data');
  const early=W([T-35*6e4,T-25*6e4]); if(early.length&&b.v-early[0].v>15) flags.push('glucose was already rising');
  if(lvLogged.some(l=>l.t>T+20*6e4&&l.t<T+150*6e4)) flags.push('another meal within 2.5 h');
  return {base:b.v,peak:Math.max(pk.v,b.v),tp:Math.max(5,Math.round((pk.t-T)/6e4)),flags};
}
function lvSpark(T){
  const pts=lvSeries.filter(p=>p.t>=T-30*6e4&&p.t<=T+180*6e4); if(pts.length<2) return '';
  const lo=Math.min(...pts.map(p=>p.v))-5, hi=Math.max(...pts.map(p=>p.v))+5;
  const X=t=>(t-(T-30*6e4))/(210*6e4)*120, Y=v=>36-(v-lo)/(hi-lo||1)*34;
  return `<svg viewBox="0 0 120 38" aria-hidden="true"><line x1="${X(T)}" x2="${X(T)}" y1="0" y2="38" stroke="var(--line-2)" stroke-dasharray="2 2"/><polyline fill="none" stroke="var(--blue)" stroke-width="1.8" stroke-linejoin="round" points="${pts.map(p=>X(p.t).toFixed(1)+','+Y(p.v).toFixed(1)).join(' ')}"/></svg>`;
}
function lvRender(){
  const el=$('lvList');
  if(!lvEvents.length){ el.innerHTML='<div class="lv-empty">No meals found in the last 60 days of this file. Add a meal time above.</div>'; return; }
  const fmtT=t=>new Date(t).toLocaleString(undefined,{weekday:'short',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
  el.innerHTML=lvEvents.map((e,i)=>{ const ok=e.base!=null&&e.peak!=null; const bad=e.flags.length>0;
    return `<div class="lvr${bad?' bad':''}" data-i="${i}">
      <input class="inc" type="checkbox" data-lvinc="${i}" ${e.inc?'checked':''} ${ok?'':'disabled'} aria-label="Share this meal">
      <div class="meta"><b>${escapeHTML(fmtT(e.t))}</b><small>${e.kind==='logged'?'Logged: '+escapeHTML(e.label):e.kind==='manual'?'Added by you':escapeHTML(e.label)}</small>
        ${ok?`<small class="lvnums">${e.base} → ${e.peak} mg/dL (+${e.peak-e.base}) at ${e.tp} min</small>`:''}
        ${bad?`<small class="warn">⚠ ${escapeHTML(e.flags.join(', '))}</small>`:''}</div>
      ${lvSpark(e.t)}
      ${ok?`<div class="pick"><input list="foodList" data-lvfood="${i}" placeholder="Which food or meal?" value="${escapeHTML(e.food)}" aria-label="Food for this meal"><input type="number" min="0.5" max="5" step="0.5" data-lvsv="${i}" value="${e.sv}" aria-label="Servings"></div>`:''}
    </div>`; }).join('');
}
$('lvFile').addEventListener('change',e=>{
  const f=e.target.files[0]; e.target.value=''; if(!f) return;
  if(f.size>40e6){ $('lvStat').textContent='That file is too large. Export a shorter date range.'; return; }
  $('lvStat').textContent='Reading your file…';
  const rd=new FileReader();
  rd.onload=()=>{ try{ lvRaw=lvParse(String(rd.result)); $('lvFmt').value=guessFmt(lvRaw.rows.map(r=>r[lvRaw.cT])); lvBuild(); }catch(err){ $('lvStat').textContent=err.message||'Could not read this file.'; $('lvBody').hidden=true; } };
  rd.onerror=()=>{ $('lvStat').textContent='Could not read this file.'; };
  rd.readAsText(f);
});
$('lvFmt').addEventListener('change',()=>{ if(lvRaw) lvBuild(); });
$('lvAddT').addEventListener('click',()=>{
  const v=$('lvWhen').value; if(!v||!lvSeries.length) return; const t=new Date(v).getTime(); if(!Number.isFinite(t)) return;
  lvEvents.unshift({t,kind:'manual',label:'',...lvMeasure(t),inc:false,food:'',sv:1}); lvEvents.sort((a,b)=>b.t-a.t); lvRender();
});
$('lvList').addEventListener('change',e=>{
  const inc=e.target.closest('[data-lvinc]'), fd=e.target.closest('[data-lvfood]'), sv=e.target.closest('[data-lvsv]');
  if(inc) lvEvents[+inc.dataset.lvinc].inc=inc.checked;
  if(sv) lvEvents[+sv.dataset.lvsv].sv=Math.max(0.5,Math.min(5,Number(sv.value)||1));
  if(fd){ const ev=lvEvents[+fd.dataset.lvfood]; ev.food=fd.value; const m=FOODS.find(f=>f.name.toLowerCase()===fd.value.trim().toLowerCase()); if(m&&!ev.flags.length){ ev.inc=true; const cb=$('lvList').querySelector(`[data-lvinc="${fd.dataset.lvfood}"]`); if(cb) cb.checked=true; } }
});
$('lvShare').addEventListener('click',async()=>{
  const msg=$('lvMsg'); const say=(t,ok)=>{ msg.textContent=t; msg.className='fmsg '+(ok?'ok':'err'); };
  if(!cdb||!cuid||cCanWrite===false){ say('Sharing is not available in this view. You can still review your meals here.',false); return; }
  if(!$('lvConsent').checked){ say('Please tick the consent box to share.',false); return; }
  const prof=$('fRead').querySelector('[name=prof]').value;
  const sel=lvEvents.filter(e=>e.inc&&e.base!=null&&e.peak!=null);
  if(!sel.length){ say('Tick at least one meal and choose its food.',false); return; }
  const out=[], missing=[];
  for(const e of sel){ const m=FOODS.find(f=>f.name.toLowerCase()===e.food.trim().toLowerCase()); if(!m){ missing.push(e); continue; }
    if(myReads.some(r=>r.fid===m.id&&r.at===e.t)) continue;
    out.push({fid:m.id,sv:e.sv,base:e.base,peak:e.peak,tp:Math.min(240,e.tp),prof,dev:'FreeStyle Libre',at:e.t}); }
  if(missing.length){ say(`Choose a food from the suggestions for ${missing.length} ticked meal${missing.length>1?'s':''}.`,false); return; }
  if(!out.length){ say('These meals were already shared.',true); return; }
  try{ await cdb.doc('readings/'+cuid).set({items:[...myReads,...out].slice(-500)}); say(`Shared ${out.length} reading${out.length>1?'s':''}. Thank you!`,true); lvEvents.forEach(e=>{ if(e.inc) e.inc=false; }); lvRender(); }
  catch(err){ say('Could not share. You may not have permission to share here.',false); }
});

$('fRead').addEventListener('submit',async e=>{
  e.preventDefault(); const fm=e.target; if(!cdb||!cuid) return;
  if(!fm.checkValidity()){ fmsg(fm,'Please fill in every field and tick the consent box.',false); return; }
  const d=Object.fromEntries(new FormData(fm));
  const match=FOODS.find(f=>f.name.toLowerCase()===d.food.trim().toLowerCase());
  if(!match){ fmsg(fm,'Pick a food from the suggestions so we can match it.',false); return; }
  const r={fid:match.id,sv:+d.servings,base:+d.base,peak:+d.peak,tp:+d.tpeak,prof:d.prof,dev:d.device,at:Date.now()};
  if(r.peak<r.base){ fmsg(fm,'The peak should be at or above the starting value.',false); return; }
  try{ await cdb.doc('readings/'+cuid).set({items:[...myReads,r].slice(-500)}); fm.reset(); fmsg(fm,'Thank you. Your reading now counts toward the community average.',true); }
  catch(err){ fmsg(fm,'Could not share. You may not have permission to share here.',false); }
});
$('feed').addEventListener('click',async e=>{
  const v=e.target.closest('[data-vote]'), m=e.target.closest('[data-mod]');
  try{
    if(v&&cdb&&cuid){ const k=v.dataset.vote; const next={...cMyVotes}; if(next[k]) delete next[k]; else next[k]=1; await cdb.doc('votes/'+cuid).set({v:next}); }
    if(m&&cdb&&cOwner){ const k=m.dataset.mod; const next={...cApproved}; if(next[k]) delete next[k]; else next[k]=true; await cdb.doc('moderation/approved').set({keys:next}); }
  }catch(err){ toast('That change could not be saved.'); }
});
$('delMine').addEventListener('click',async()=>{
  if(!cdb||!cuid) return;
  if(!confirm('Delete all your submitted foods, CGM readings and votes? This cannot be undone.')) return;
  try{ await Promise.all(['foods','readings','votes'].map(c=>cdb.doc(c+'/'+cuid).delete())); toast('Your contributions were deleted'); }catch(err){ toast('Could not delete. Try again.'); }
});
setupCommunity();


/* =========================================================
   REDESIGN: live hero, palette, scrollspy, theme, tweening
   ========================================================= */
const RM = matchMedia('(prefers-reduced-motion: reduce)').matches;
function tweenNum(el,to){
  if(!el) return; to=Math.round(to); const from=el._v??to; el._v=to;
  if(RM||from===to){ el.textContent=to; return; }
  const t0=performance.now(), d=600;
  cancelAnimationFrame(el._raf);
  const step=now=>{ const k=Math.min(1,(now-t0)/d), e=1-Math.pow(1-k,3); el.textContent=Math.round(from+(to-from)*e); if(k<1) el._raf=requestAnimationFrame(step); };
  el._raf=requestAnimationFrame(step);
}

/* ---- hero live curve ---- */
const HERO_MEALS=[['idli_coffee','Idli + filter coffee'],['masala_dosa_coffee','Masala dosa + coffee'],['white_rice','White rice'],['rajma_chawal','Rajma chawal'],['dal_chawal_ghee','Dal chawal + ghee'],['pesarattu','Pesarattu'],['chicken_biryani','Chicken biryani'],['pav_bhaji','Pav bhaji'],['sushi_salmon','Salmon sushi'],['cola','Cola']].filter(([id])=>F[id]);
let heroId=HERO_MEALS[0][0], heroPts=null, heroGhost=null, heroBase=90, heroAnim=0, heroPeakT=0;
const NPTS=61;
function curvePts(pr){ const a=[]; for(let i=0;i<NPTS;i++) a.push(curveAt(pr,i*3)); return a; }
const HROW1=['idli_coffee','white_rice','rajma_chawal','samosa_chai','filter_coffee','pesarattu','curd','masala_dosa_coffee','chicken_biryani','dal_chawal_ghee','pav_bhaji','oats_banana'].filter(id=>F[id]);
const HROW2=['foxtail','mango','jalebi','chole_bhature','eggs','sabudana','dal_chawal','naan','sushi_salmon','cola','pongal_vada_coffee','salad','chapati','gulab_jamun'].filter(id=>F[id]);
const hchip=(id,dup)=>{ const f=F[id], s=f._score; return `<button class="hchip" type="button" data-hm="${id}" aria-pressed="${id===heroId}" ${dup?'tabindex="-1" aria-hidden="true"':''}><span class="e" aria-hidden="true">${f.emoji}</span>${escapeHTML(f.name)}<span class="hs ${cls(s)}" aria-label="score ${s} of 10">${s}</span></button>`; };
$('hRow1').innerHTML=HROW1.map(id=>hchip(id,false)).join('')+HROW1.map(id=>hchip(id,true)).join('');
$('hRow2').innerHTML=HROW2.map(id=>hchip(id,false)).join('')+HROW2.map(id=>hchip(id,true)).join('');
$('hChips').addEventListener('click',e=>{ const b=e.target.closest('[data-hm]'); if(!b) return; heroId=b.dataset.hm; $('hChips').querySelectorAll('.hchip').forEach(x=>x.setAttribute('aria-pressed',x.dataset.hm===heroId)); renderHero(); });
$('hSteady').addEventListener('change',renderHero);
document.querySelectorAll('.hseg [data-p]').forEach(b=>b.addEventListener('click',()=>renderHero()));
$('hCount').textContent=new Intl.NumberFormat('en-IN').format(FOODS.filter(f=>!f.parts).length);
function heroGeom(){ const box=$('hLive'), W=box.clientWidth, H=box.clientHeight; const wrapW=Math.min(1200,W); const pad=Math.max(18,(W-wrapW)/2+Math.min(56,W*0.045)); return {W,H,pad}; }
function renderHero(){
  const f=F[heroId]; const steady=$('hSteady').checked;
  const base=new Map([[heroId,1]]);
  const asIs=predict(base,prof,NOH);
  let pr=asIs, info='';
  if(steady){ const r=buildSteps(f); const last=r.steps[r.steps.length-1]; pr=last.pr; const n=r.steps.length-1;
    info = n ? `Steadier version: <b class="gain">−${Math.round(asIs.peak-pr.peak)} mg/dL</b> with ${n} change${n>1?'s':''}: ${r.steps.slice(1).map(s=>escapeHTML(s.title.charAt(0).toLowerCase()+s.title.slice(1))).join(', ')}.` : 'Already steady. None of our changes move it by more than a few points.'; }
  else { const st=settleText(asIs); info=`<b>+${Math.round(asIs.rise)} mg/dL</b>, peaking around ${Math.round(asIs.tp/5)*5} min${st?`, settling in about ${st}`:', still raised at 3 h'}.`; }
  $('hMeta').innerHTML=info; $('hLink').href='#food/'+heroId; $('hLink').textContent=steady?'See every step':'See how to steady it';
  const target=curvePts(pr); heroGhost=steady?curvePts(asIs):null; heroBase=pr.base; heroPeakT=pr.tp;
  const peakEl=$('hPeak'); tweenNum(peakEl,pr.peak); const zl=PROF[prof].lim; const zi=pr.peak>=zl[1]?['High','#FF5C7A']:pr.peak>=zl[0]?['Moderate','#FBBF24']:['Steady','#34D399']; $('hZone').querySelector('span').textContent=zi[0]+(steady?' after changes':''); $('hZone').style.setProperty('--z',zi[1]); peakEl.style.setProperty('color',zi[1],'important');
  const from=heroPts||target.map(()=>pr.base);
  cancelAnimationFrame(heroAnim);
  if(RM){ heroPts=target; drawHero(); return; }
  const t0=performance.now(), d=heroPts?750:1400;
  const step=now=>{ const k=Math.min(1,(now-t0)/d), e=1-Math.pow(1-k,4); heroPts=target.map((v,i)=>from[i]+(v-from[i])*e); drawHero(); if(k<1) heroAnim=requestAnimationFrame(step); };
  heroAnim=requestAnimationFrame(step);
}
let heroCursor=null;
function drawHero(){
  if(!heroPts) return; const {W,H,pad}=heroGeom(); if(!W) return;
  const svg=$('hChart'); svg.setAttribute('viewBox',`0 0 ${W} ${H}`);
  const all=[...heroPts,...(heroGhost||[])]; const top=Math.max(prof==='none'?190:250, Math.ceil((Math.max(...all)+25)/20)*20); const lo=heroBase-28;
  const X=t=>pad+(W-2*pad)*t/180, Y=v=>10+(H-40)*(1-(v-lo)/(top-lo));
  const path=pts=>pts.map((v,i)=>(i?'L':'M')+X(i*3).toFixed(1)+','+Y(v).toFixed(1)).join('');
  let pk=0; heroPts.forEach((v,i)=>{ if(v>heroPts[pk]) pk=i; });
  const pv=heroPts[pk], col=pv>=PROF[prof].lim[1]?'#FF5C7A':pv>=PROF[prof].lim[0]?'#FBBF24':'#34D399', line='#F5F5F7';
  let s=`<defs><linearGradient id="hg" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${col}" stop-opacity=".26"/><stop offset="1" stop-color="${col}" stop-opacity="0"/></linearGradient></defs>`;
  for(const v of [140,180]) if(v<top&&v>lo) s+=`<line x1="${pad}" x2="${W-pad}" y1="${Y(v)}" y2="${Y(v)}" stroke="rgba(255,255,255,.14)" stroke-dasharray="2 6"/><text x="${W-pad}" y="${Y(v)-8}" text-anchor="end">${v===140?'140, healthy limit':'180, diabetes target'}</text>`;
  s+=`<line x1="${pad}" x2="${W-pad}" y1="${Y(heroBase)}" y2="${Y(heroBase)}" stroke="rgba(255,255,255,.12)"/>`;
  [0,60,120,180].forEach(t=>{ s+=`<text x="${X(t)}" y="${H-8}" text-anchor="${t===0?'start':t===180?'end':'middle'}">${t===0?'You eat':t/60+' h'}</text>`; });
  if(heroGhost) s+=`<path d="${path(heroGhost)}" fill="none" stroke="rgba(255,255,255,.35)" stroke-width="2" stroke-dasharray="4 6"/>`;
  const d=path(heroPts);
  s+=`<path d="${d}L${X(180)},${Y(lo)}L${X(0)},${Y(lo)}Z" fill="url(#hg)"/><path d="${d}" fill="none" stroke="${col}" stroke-width="3" stroke-linejoin="round" stroke-linecap="round"/>`;
  const px=X(pk*3), py=Y(pv);
  if(pv-heroBase>2) s+=`<line x1="${px}" x2="${px}" y1="${py}" y2="${Y(heroBase)}" stroke="${col}" stroke-opacity=".5" stroke-dasharray="2 4"/><circle cx="${px}" cy="${py}" r="6" fill="${col}"/><circle cx="${px}" cy="${py}" r="12" fill="${col}" fill-opacity=".18"/>`;
  if(heroCursor!=null){ const i=Math.max(0,Math.min(NPTS-1,heroCursor/3)); const lo2=Math.floor(i), hi2=Math.min(NPTS-1,lo2+1); const v=heroPts[lo2]+(heroPts[hi2]-heroPts[lo2])*(i-lo2);
    s+=`<line x1="${X(heroCursor)}" x2="${X(heroCursor)}" y1="0" y2="${H-24}" stroke="rgba(255,255,255,.5)"/><circle cx="${X(heroCursor)}" cy="${Y(v)}" r="5" fill="#fff"/>`;
    const sc=$('hScrub'); sc.style.left=X(heroCursor)+'px'; sc.style.top=Math.max(0,Y(v)-44)+'px'; const mm=Math.round(heroCursor); sc.innerHTML=`${Math.round(v)} mg/dL<small>${mm>=60?Math.floor(mm/60)+' h '+(mm%60)+' min':mm+' min'}</small>`; }
  svg.innerHTML=s;
}
$('hLive').addEventListener('pointermove',e=>{ const {W,pad}=heroGeom(); const r=$('hLive').getBoundingClientRect(); const t=((e.clientX-r.left)-pad)/(W-2*pad)*180; if(t<0||t>180){ heroCursor=null; $('hScrub').style.opacity=0; } else { heroCursor=t; $('hScrub').style.opacity=1; } drawHero(); });
$('hLive').addEventListener('pointerleave',()=>{ heroCursor=null; $('hScrub').style.opacity=0; drawHero(); });
new ResizeObserver(()=>drawHero()).observe($('hLive'));

/* ---- command palette ---- */
let palSel=0, palItems=[], palOpener=null;
function palSearch(q){
  const toks=q.toLowerCase().split(/\s+/).filter(Boolean);
  let list=toks.length?FOODS.filter(f=>matches(f,toks)):FOODS.filter(f=>f.parts||HERO_MEALS.some(([id])=>id===f.id));
  const rank=f=>(f.src==='U'?2:0)+(toks.length&&f.name.toLowerCase().startsWith(toks[0])?0:1);
  list=list.slice(0,4000).sort((a,b)=>rank(a)-rank(b)||a.name.length-b.name.length).slice(0,40);
  palItems=list; palSel=0; palRender();
}
function palRender(){
  const ul=$('palList');
  if(!palItems.length){ ul.innerHTML=`<li class="pal-empty" role="option" aria-disabled="true">No match. Try fewer words, like "rice" or "dosa".</li>`; return; }
  ul.innerHTML=palItems.map((f,i)=>`<li role="option" id="po${i}" data-i="${i}" aria-selected="${i===palSel}"><span class="e" aria-hidden="true">${f.emoji}</span><span class="n">${escapeHTML(f.name)}<small>${f.parts?'Meal with '+f.parts.length+' parts':escapeHTML(f.serving)+(f.src==='U'?', USDA':'')}</small></span><span class="pk">${f._peak}<small>peak</small></span><button class="add" type="button" data-paladd="${f.id}" aria-label="Add ${escapeHTML(f.name)} to plate">+</button></li>`).join('');
  $('palQ').setAttribute('aria-activedescendant','po'+palSel);
  const cur=ul.querySelector('[aria-selected="true"]'); cur&&cur.scrollIntoView({block:'nearest'});
}
let palMode='open';
function palOpen(mode){ palMode=mode==='add'?'add':'open'; $('palQ').placeholder=palMode==='add'?'Add food to your plate':'Search any food or meal'; $('palFoot').innerHTML=palMode==='add'?'<span><kbd>↑</kbd><kbd>↓</kbd> move</span><span><kbd>↵</kbd> add to plate</span><span><kbd>esc</kbd> done</span>':'<span><kbd>↑</kbd><kbd>↓</kbd> move</span><span><kbd>↵</kbd> open</span><span><kbd>+</kbd> add to plate</span>'; palOpener=document.activeElement; $('pal').hidden=false; $('palQ').value=''; palSearch(''); setTimeout(()=>$('palQ').focus(),0); document.body.style.overflow='hidden'; }
function palClose(){ $('pal').hidden=true; document.body.style.overflow=''; palOpener&&palOpener.focus&&palOpener.focus(); }
function palGo(f){ if(palMode==='add'){ add(f.id,1); toast(`${f.name} added to plate`); $('palQ').select(); return; } palClose(); location.hash='#food/'+f.id; }
document.addEventListener('click',e=>{ if(e.target.closest('[data-palette-add]')){ e.preventDefault(); palOpen('add'); } else if(e.target.closest('[data-palette]')){ e.preventDefault(); palOpen('open'); } });
$('pal').addEventListener('click',e=>{ if(e.target===$('pal')) palClose(); const a=e.target.closest('[data-paladd]'); if(a){ e.stopPropagation(); add(a.dataset.paladd,1); toast(`${F[a.dataset.paladd].name} added to plate`); return; } const li=e.target.closest('li[data-i]'); if(li) palGo(palItems[+li.dataset.i]); });
$('palQ').addEventListener('input',e=>palSearch(e.target.value));
$('palQ').addEventListener('keydown',e=>{
  if(e.key==='ArrowDown'){ e.preventDefault(); palSel=Math.min(palItems.length-1,palSel+1); palRender(); }
  else if(e.key==='ArrowUp'){ e.preventDefault(); palSel=Math.max(0,palSel-1); palRender(); }
  else if(e.key==='Enter'){ e.preventDefault(); if(palItems[palSel]) palGo(palItems[palSel]); }
  else if(e.key==='+'&&palItems[palSel]){ e.preventDefault(); add(palItems[palSel].id,1); toast(`${palItems[palSel].name} added to plate`); }
  else if(e.key==='Escape'){ e.preventDefault(); palClose(); }
});
document.addEventListener('keydown',e=>{
  const ae=document.activeElement; const typing=(ae.tagName==='INPUT'&&!/^(checkbox|radio|button|submit|range|file)$/i.test(ae.type))||/^(TEXTAREA|SELECT)$/.test(ae.tagName)||ae.isContentEditable;
  if(((e.key==='k'||e.key==='K')&&(e.metaKey||e.ctrlKey))||(e.key==='/'&&!typing)){ e.preventDefault(); $('pal').hidden?palOpen():palClose(); }
  else if(e.key==='Escape'&&!$('pal').hidden) palClose();
});

/* ---- scrollspy ---- */
const spyLinks=[...document.querySelectorAll('.nav-links a[href^="#"]:not(.pill)')];
const spy=new IntersectionObserver(es=>{ es.forEach(en=>{ if(en.isIntersecting){ spyLinks.forEach(a=>a.setAttribute('aria-current',a.getAttribute('href')==='#'+en.target.id?'true':'false')); } }); },{rootMargin:'-40% 0px -55% 0px'});
spyLinks.forEach(a=>{ const s=document.getElementById(a.getAttribute('href').slice(1)); if(s) spy.observe(s); });

/* ---- theme ---- */
const THEMES=['auto','light','dark'];
function applyTheme(t){ if(t==='auto') document.documentElement.removeAttribute('data-theme'); else document.documentElement.setAttribute('data-theme',t); $('themeBtn').setAttribute('aria-label','Colour theme: '+(t==='auto'?'automatic':t)); $('themeBtn').title='Theme: '+(t==='auto'?'automatic':t); try{ localStorage.setItem('mytr-theme',t); }catch(e){} }
let theme='auto'; try{ theme=localStorage.getItem('mytr-theme')||'auto'; }catch(e){}
applyTheme(THEMES.includes(theme)?theme:'auto');
$('themeBtn').addEventListener('click',()=>{ theme=THEMES[(THEMES.indexOf(theme)+1)%3]; applyTheme(theme); toast('Theme: '+(theme==='auto'?'automatic':theme)); });

renderHero();

renderZones();
